INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593522633', 'Reparo Bico Injetor Gm Omega 1992 a 1995 - 187831 - 1246', 'Reparo Bico Injetor Gm Omega 1992 a 1995 187831 1246 2.0 8v /3.0 12v Gasolina - (Multi Point) (Sistema Bosch) (4 Filtros + 4 Ponteiras + 4 Anéis + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 43.41, 43.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reoi-m2f4lzrztuws97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23593522633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897462595', 'Regulador Pressão Fiat Fiorino 2002 a 2010 - 133746 - 1183', 'Regulador Pressão Fiat Fiorino 2002 a 2010 133746 1183 MOTOR 1.0/1.3 FIRE - 3.5 BAR (PRESSÃO) O sistema de injeção eletrônica de combustível tem por objetivo proporcionar ao motor um melhor rendimento com mais economia, em todos os regimes de funcionamento, fornecendo uma dosagem de combustível mais precisa com resposta mais rápida. Ele tem como função ajustar a pressão em toda a linha de combustível, desde a saída da bomba até os bicos injetores. O Regulador de Pressão pode estar montado em três posições. A localização depende do sistema de injeção eletrônica utilizado.', 90.98, 90.98, NULL, 'Automobiles > Automobile Spare Parts > Fuel System', 'https://cf.shopee.com.br/file/br-11134201-820li-mqxdu6wi8uthbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897462595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899889991', 'Cafeteira Elétrica Cadence, Desperta Contrast, 750mls, 600W, Preta - CAF338', 'A Cafeteira Elétrica Desperta é perfeita para quem tem uma rotina atarefada e precisa de um cafezinho feito de forma simples e rápida. Fácil de limpar e compacta, é a sua melhor aliada na rotina! Seu design enaltece qualquer cozinha com seus detalhes e acabamentos. Possui uma jarra de vidro fácil de lavar, que não deixa resíduos nem odores, e com capacidade para fazer 18 cafés, ou 750ml. A base de aquecimento não queima o café, mantendo-o aquecido na temperatura ideal. Com 600W de potência (disponível em 127V e 220V), é eficiente para preparos mais rápidos. A cafeteira possui indicadores de medida de água na parte interna e de café na jarra, facilitando o preparo. Características do produto: Marca: Cadence Referência de modelo: CAF338 Cor: Preto Tipo: Elétrica Potência: 600 Watts Conserva líquidos quentes: Sim Jarra: De vidro Capacidade da jarra: 0,75 litros Capacidade de cafés: 18 cafés Reservatório de água: Sim Sistema corta pingos: Sim Marcação de nível: Sim Certificação Inmetro: BRA19/01580 Consumo de energia: 0,6 kW/h Dimensões: Altura: 27,70 cm Largura: 22,30 cm Profundidade: 14,90 cm Peso: 0,90 kg Garantia do Fornecedor: 12 Meses', 131.51, 131.51, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824hv-mfbl6dy9bkzwf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F21899889991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
