INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499048015', 'Centrífuga de Roupas Britânia BCR15B 15Kg Cesto em Inox', 'Segurança, beleza e eficiência reunidos em um único produto. A Centrífuga de Roupas Britânia 15Kg chegou para otimizar seu tempo e tornar seu cotidiano mais funcional. Permitindo centrifugar uma grande quantidade de roupas até 15kg de roupas molhadas até 5 kg de roupas secas. Além de contar com cesto extra grande, a Centrifuga BCR15B conta com extração de até 70 da água das roupas. Dimensões: Altura: 79,00 cm Largura: 43,50 cm Profundidade: 43,00 cm Peso: 6,95 kg Garantia do Fornecedor: 12 Meses', 664.37, 619.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-82589-mg287nkt3x8vd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F22499048015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299247114', 'Bóia Tanque Sensor Nível Gm Onix 2017 a 2020 - 839654 - T010225', 'Bóia Tanque Sensor Nível Gm Onix 2017 a 2020 839654 T010225 1.0 8v Flex - Não se Aplica em Bombas Bosch O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 114.22, 114.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd3v-lufiuhwvagw924', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18299247114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997462800', 'Tampa Reservatório Expansão Ford Ecosport 2013 a 2017 - 196813 - 22098', 'Tampa Reservatório Expansão Ford Ecosport 2013 a 2017 196813 22098 1,45 BAR (TAMPA PRETA) Além de fechar o reservatório de expansão, esta tampa também mantém a pressão do sistema, através de uma válvula que se abre, dando passagem ao excesso de pressão. O controle da pressão faz com que o líquido tenha uma circulação completa, atingindo todos os pontos do motor, tenha um ponto de ebulição mais elevado, impede a formação de vapor no interior do motor, permite a entrada de ar atmosférico quando a temperatura do líquido abaixa.', 40.36, 40.36, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd3w-luf6b1lwkjadbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23997462800', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898365337', 'Bomba Combustível ASTRA 1998/2010 - 71415 - 10107', 'Bomba Combustível ASTRA 1998/2010 1.8/2.0 16v - Gasolina - 3 Bar - 12V - 100L/H - MultipontoPodemos dividir as bombas de combustível elétricas em dois tipos, interna e externa ao tanque. A interna trabalha submersa aspirando o combustível diretamente do fundo do tanque para as mangueiras de abastecimento que ligam aos bicos injetores. A externa trabalha fixada ao chassi do veículo, próxima ao tanque ou ao motor, sugando o combustível do tubo coletor localizado no tanque', 69.24, 69.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reoc-m832xrohpamt98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898365337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
