INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497249287', 'Operation Wolf Returns First Mission Rescue Edition Switch Midia Fisica', 'OPERATION WOLF RETURNS FIRST MISSION RESCUE EDITION SWITCH **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA - ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com Nintendo SWITCH, LITE E OLED; - Versão: Importada; - Legenda ou Texto: Inglês, Francês, Espanhol; - Jogadores: 1 a 2; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo OPERATION WOLF RETURNS FIRST MISSION RESCUE EDITION SWITCH; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia - Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO Uma reinterpretação de um dos jogos fundadores do gênero de atiradores de trem, lançado como um jogo de arcade em 1987, a Operação Wolf retorna: a primeira missão adota o mesmo DNA que no jogo original (ação sustentada em uma atmosfera direto dos filmes de ação dos anos 80) mas oferece um novo design. Alguns meses atrás, uma nova organização criminosa apareceu. Além de tráfico de armas e drogas, desenvolveu uma nova arma superpoderosa. Depois de descobrir várias das bases da organização, lideradas pelo misterioso general Viper, dois agentes são despachados para aprender mais sobre essa arma e libertar os reféns realizados nos campos circundantes. A reinterpretação do jogo de ação do Arcade Cult lançado em 1987 Nova direção artística Adição de vozes no estilo paródia Jogabilidade focada na ação ininterrupta Uma campanha que pode ser jogada sozinha ou com dois jogadores Modo de sobrevivência (ondas de combate aos inimigos) Um arsenal de armas (Uzi, espingarda, lançador de granadas, etc.)', 209.89, 209.89, NULL, 'Gaming & Consoles > Video Games > Switch', 'https://cf.shopee.com.br/file/sg-11134201-7rblk-lpkzsnrr0eq7eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F23497249287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44171741744', 'Tênis Fila Maxxi Lite Preto Marrom e Off White - Masculino', 'Mais leveza e energia em cada treino! Tênis Fila Maxxi Lite Preto Marrom e Off White - Masculino Parte superior do formulário Parte superior do formulário Ficha Técnica: Marca: Fila Cor: Preto, marrom e off white Indicação: Treino e academia Cabedal: Mesh respirável para ajuste perfeito Gênero: Masculino Palmilha: EVA Sola: EVA emborrachado com maior tração Fechamento: Cadarço Amortecimento: Médio Estabilidade: Alta Tecnologias: ENERGIZED RUBBER - transforma impacto em propulsão Entressola: EVA com tecnologia Energized Detalhes: Design moderno e leve com logo da marca nas laterais O Tênis Fila Maxxi Lite foi desenvolvido para quem não abre mão de conforto e performance. Seu cabedal em mesh garante respirabilidade e ajuste perfeito, acompanhando seus movimentos. Porque investir: A entressola com tecnologia ENERGIZED RUBBER transforma o impacto em energia, oferecendo mais propulsão e eficiência em cada passada. Já o solado em EVA emborrachado garante tração e durabilidade, ideal para treinos intensos e diários. Um modelo que une estilo, leveza e performance para potencializar seus resultados. Conteúdo da embalagem: 1 par de Tênis Fila Maxxi Lite Preto Marrom e Off White - MasculinoParte superior do formulário', 349.99, 267.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824hh-mf4fqgb46xoo09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F44171741744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50150883176', 'Tênis Coca Cola Stream Town Branco - Feminino', 'Estilo urbano e conforto que se destacam em qualquer lugar! Tênis Coca Cola Stream Town Branco - Feminino Ficha Técnica: Marca: Coca-Cola Cor: Branco com detalhes em marrom e rose Gênero: Feminino Indicado: Dia a Dia e passeios Cabedal: Sintético Palmilha: EVA Sola: Borracha Fechamento: Cadarço Amortecimento: Macio Estabilidade: Neutro Tecnologias: Solado antiderrapante para segurança em diversos tipos de solo Entressola: EVA com suporte anatômico Detalhes: Design streetwear, visual clean e moderno Com design sofisticado e pegada streetwear, o Tênis Coca Cola Stream Town é ideal para mulheres que não abrem mão de conforto aliado ao estilo. Porque investir: O cabedal em material sintético traz durabilidade e sofisticação, enquanto a palmilha em EVA e o solado antiderrapante garantem pisadas macias e seguras. Um modelo leve e moderno para usar com jeans, vestidos ou peças mais ousadas do street style. Conteúdo da embalagem: 1 par de Tênis Coca Cola Stream Town Branco – Feminino', 179.99, 151.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-821g2-mgpkt90a6xakb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F50150883176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
