INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691954985', 'KIT RELACAO - 1045 XR 200 / NX 200 93/02 (43D X 13D 520H X 108L)', 'KIT RELAÇÃO NATION (COROA + PINHÃO + CORRENTE) POSSUI SELO INMETRO Moto Compatível: XR 200 / NX 200 1993 ATÉ 2002 Pinhões Os pinhões são produzidos em aço 1045 liga com níquel, cromo, e molibdênio o que lhe confere melhor temperabilidade para garantir a durabilidade e a tenacidade necessária para o melhor desempenho de seu conjunto de transmissão. Coroas As coroas são fabricadas em processo de usinagem em CNC para oferecer a maior concentricidade e perfil de dente ideal para maior vida útil, transferência de potência máxima e durabilidade nos mais diversos terrenos e condições adversas. Corrente - Corrente pré tensionada (não "estica" apresentando folgas). - Alinhamento milimétrico das placas, garantindo assim a distribuição da força - Pino central reforçado e em aço temperado. - Placas em aço 1045 temperado com alivio de tensões. As correntes de transmissão NATION são feitos em aço 1045 ultra resistente, que garante maior durabilidade e proporciona o mesmo tempo de vida útil frente ao original. Combinada com materiais especiais usados na fabricação dos pinos, roletes e elos, além de um lubrificante especial, asseguram alta qualidade e vida útil no uso em rodovias. XR 200 / NX 200 93/02 (43D X 13D 520H X 108L)', 176.83, 176.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugs0dhzegwhb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F23691954985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57102693592', 'Bala Azedinha Colorida', 'Bala Azedinha Colorida Macia, vibrante e cheia de sabor, mistura o doce com o toque cítrico na medida certa. Perfeita para quem gosta de doces divertidos e com um azedinho irresistível. Ingredientes: Açúcar, xarope de glucose transgenico, amido de milho modificado, transgenico, aromatizantes naturais de laranja e tangerina e artificiais de abacaxi, anis,coco,framboesa,morango e uva,corantes artificiais. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 18.63, 18.63, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhxg7akup88x1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F57102693592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6288888396', 'Frigideira Dupla Omeleteira Antiaderente 18Cm Preto Nacional', 'A Frigideira Dupla Omeleteira com Revestimento Antiaderente 18cm é o segredo para preparar omeletes perfeitas, macias e douradas em poucos minutos, sem esforço e sem sujeira. Seu design inteligente com duas partes encaixáveis permite virar o preparo de forma prática, garantindo um cozimento uniforme dos dois lados. Ideal para quem ama começar o dia com uma refeição leve e saborosa ou surpreender a família com novas receitas, ela torna o momento de fazer omelete ainda mais prazeroso e simples. Produzida em alumínio, distribui o calor de maneira homogênea, evitando pontos queimados e garantindo o sabor natural dos ingredientes. O revestimento antiaderente permite cozinhar com menos óleo, mantendo a saúde em primeiro lugar e facilitando a limpeza. Além disso, o cabo de baquelite é resistente e antitérmico, oferecendo total segurança ao manusear, mesmo com a frigideira quente. Seja para preparar omeletes, panquecas, tortilhas ou frituras, a omeleteira antiaderente é indispensável para quem busca praticidade, economia e qualidade na cozinha. Um toque de modernidade e eficiência que transforma qualquer receita simples em um verdadeiro momento gourmet. Descubra o prazer de cozinhar com leveza e sabor. Experimente a sua e sinta a diferença no dia a dia. Ficha Técnica: Medidas e dimensões: Altura: 4,2cm | Largura: 18cm | Comprimento: 34cm | Capacidade: 0,9L Material do corpo: Alumínio Material da alça/cabo: Baquelite Marca: Alumínio Nacional Fabricante: Alumínio Nacional Garantia: 90 dias Composição: 01x Frigideira Dupla Omeleteira', 51.9, 43.9, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/br-11134207-820lp-mlrxyxpbdddz99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359066629%2F6288888396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593134150', 'Vestido Plus Size para Noiva de Festa Junina com Tiara de Véu', 'Itens inclusos: 01 Vestido 01 Tiara com véu Tamanhos: GG - Numeração de roupa 46 a 48. XGG - Numeração de roupa 48 a 50. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. Especificações Técnicas Material: Saia Poliéster / Cintura Helanca. Produto: Novo, na embalagem. Produto a pronta entrega! Produto original! Procurando por vestido de Festa Junina? Chegou essa linda opção para você usar e arrasar nesse São João! Esse linda fantasia é composta por um vestido junino confeccionado em material de ótima qualidade, sendo a saia produzida em poliéster, que trás muito mais conforto na hora do uso, além disso, a saia é rica em detalhes com lindas bandeirinhas coloridas em veludo e uma linda renda ao redor da barra da saia. A região da cintura contém um espartilho falso e tecido em helanca que se ajusta super bem ao corpo e não pinica, além disso, acompanha dois laços e fitas. Para deixar a sua fantasia de novinha caipirinha ainda mais completa, acompanha tiara com véu. Ideal para Festa Junina, Arraiá, São João e muito mais. Confira! Temática de Festa Junina Acompanha Tiara Não pinica Não esquenta Super confortável Secagem rápida', 319.9, 319.9, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-7rfig-ma04stoy20zz53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F23593134150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
