INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198751840', 'Tênis Feminino Casual Dakota Da513', 'O Tênis Feminino Casual Dakota DA513 é perfeito para quem busca conforto e estilo em um calçado versátil. Com design moderno e detalhes únicos, ele é ideal para compor diversos looks. Sua sola garante maior aderência e estabilidade, além de proporcionar conforto durante o dia todo. Com materiais de alta qualidade, o tênis é durável e resistente, sendo uma ótima opção para o dia a dia. Adquira o seu agora mesmo e fique ainda mais estilosa!. MODELO: 0645130 REFERENCIA: DA513 MARCA: Dakota MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: EVA MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado DETALHES: Solado com 4 cm aproximadamente GÊNERO: Female GRUPO DE IDADE: Adult MATERIAL DO SAPATO: Sintético ESTILO DO TÊNIS: Urbano', 299.99, 299.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdw5-mcclvg4yljqv2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F22198751840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
