INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258194523', 'Lip Oil Fresh Lips - Hbl6526 - Ruby Rose', 'Fresh Lips é o lip oil que seus lábios vão amar! Com hidratação profunda, ele protege e ajuda a reparar os lábios, deixando a boca mais viçosa, macia e saudável. Um cuidado diário com brilho natural e aquele efeito de lábios bem tratados que faz toda a diferença. Modo de Uso Aplique uma camada generosa nos lábios sempre que necessário. Precauções: Uso externo. Não aplicar sobre mucosa irritada ou lesionada. Em caso de irritação, suspender o uso e procure orientação médica. Manter fora do alcance das crianças. Conserve o produto bem fechado, longe da luz e do calor excessivo.', 23.99, 19.24, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mlhvy1k70cu993', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784788471%2F58258194523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
