INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3693531279', 'Corda 3,20m Ginástica Rítmica Dicat Sports Laranja', 'Corda 3,20m Ginástica Rítmica Dicat Sports Corda trançada com fios de polipropileno e enchimento em algodão, totalizando 10mm de diâmetro. Na medida de 3,20m. Acabamento térmico nas extremidades. Disponíveis nas cores: Laranja cítrico, Verde cítrico, Verde , Vermelha, Preta, Azul, Amarela, Branca e Rosa Bebê. Corda fabricada em conformidade com as normas da FIG e o selo de qualidade ABRIESP. Indicação de Uso: Sua principal indicação, por estar dentro das conformidades da FIG, é o aparelho da Ginástica Rítmica para a categoria juvenil e adulto. Como a corda não possui peças em madeira, e é totalmente maleável pode ser utilizada como “pula corda” para atividades educativas, recreativas e de condicionamento físico. Conteúdo da Embalagem: 1 Corda 3,20m Ginástica Rítmica Dicat Sports Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagens Meramente Ilustrativas.', 59.0, 59.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/9d5f40070402d01fe3d4c48eb5991c0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F3693531279', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53211103011', 'Pulseira Bolinhas em Prata 925 Delicada e Elegante', 'A Pulseira Trio Duplo de Esferas em Prata 925 é uma joia delicada e sofisticada, perfeita para quem ama acessórios minimalistas com design moderno. O destaque da peça fica por conta dos trios de esferas lisas distribuídos pela corrente, criando um visual elegante, harmonioso e atemporal. - Material: Prata 925 - Detalhe: Trio duplo de esferas lisas - Estilo: Minimalista e sofisticado - Comprimento: Ajustável - Fecho: Argola tradicional - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma peça versátil e elegante, ideal para uso diário ou para compor mixes delicados e modernos com muito charme.', 235.0, 129.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-820la-monxlxzzin0l06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F53211103011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
