INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994211960', 'Kit 2 Unidades Genco Limpa Bordas Para Piscinas 1l', 'Poderoso detergente biodegradável para piscinas, com baixa formação de espuma e aroma agradável de citronela. Elimina depósitos de óleos e gorduras e não altera o pH da água. INSTRUÇÕES DE USO 1) Aplique LIMPA-BORDAS GENCO® em esponja e friccione sobre as áreas das bordas da piscina a serem limpas. Em seguida, enxágue com água da própria piscina. 2) Para aplicar o produto escolha esponja de consistência adequada ao trabalho e que não danifique as superfícies a serem limpas. OBSERVAÇÃO: Nunca utilize esponja de aço.', 44.23, 42.9, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-mbxoi695eefh55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490055656%2F22994211960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205049390', 'Rack De Teto Bagageiro Polo Novo 2018 19 20 21 22 23 24 2025', 'Rack de Teto Bagageiro Suporte Fixação Porta para Polo - VHIP Compatibilidade: ANOS: 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025 Quer mais espaço para VIAJAR, TRABALHAR ou levar seus equipamentos com SEGURANÇA? O Rack Teto Bagageiro Porta - VHIP é a escolha PERFEITA para quem busca praticidade, resistência, SEGURANÇA e visual moderno. Com capacidade para até 50 kg de carga, ele permite transportar malas, bicicletas, pranchas, caixas de ferramentas ou materiais de trabalho com total segurança e estabilidade, sem ocupar o espaço interno do veículo. Além disso a VHIP oferece a QUALIDADE atestada pela CERTIFICAÇÃO de Processo ISO 9001, FIQUE ATENTO antes de compra! POR QUE O RACK VHIP SEM DÚVIDAS É O MELHOR VENDIDO NO BRASIL: - Com Sistema antifurto exclusivo, que dificulta a remoção indevida e protege seu investimento. - Certificação ISO 9001 – segue padrões internacionais de qualidade e rastreabilidade. - Design esportivo com acabamento perfeito – visual moderno e elegante. - Parafusos em aço liga 12.9 – material de alta resistência e durabilidade. - Estrutura reforçada – suporta até 50 kg com segurança. - Pintura em poliéster – resistente à ferrugem e à corrosão, prolonga a vida útil. - Encaixe perfeito – instalação precisa, sem folgas (Seguir orientações do Manual de Instalação) - Não risca o carro – protege a pintura original (Seguir orientações do Manual de Instalação). - Não fura o teto – fixação inteligente sem necessidade de perfurações. - Altura ideal – evita contato e acidentes com o teto do veículo. - Haste de ajuste de pressão fixa – não solta, não trepida, garante estabilidade. - Produto novo e com garantia – segurança total na compra. VANTAGENS: - Mais segurança contra furtos graças ao sistema antifurto patenteado que dificulta a remoção. - Proteção contra ferrugem e intempéries com pintura automotiva de qualidade premium. - Instalação simples e sem danos ao veículo. - Durabilidade MUITO SUPERIOR aos racks comuns, por usar materiais de padrão industrial e seguindo normas ISO9001 no processo de produção - Estabilidade e silêncio durante o uso, sem trepidações. Ficha técnica: Peso suportado: até 50 kg Material Suporte: Aço Certificado com acabamento em pintura Poliéster Material Tubo : Aço Certificado Galvanizado Fixação: Na porta Cor: Preto fosco Instalação: Sistema de aperto rápido com proteção anti risco. Itens inclusos: 1 - Par de racks completos (2 barras) 1 - Kit de fixação com parafusos, arruelas e porcas 1 - Manual ilustrado para instalação Compre direto da nossa LOJA OFICIAL VHIP ACESSÓRIOS, atendemos todo Brasil com RAPIDEZ, QUALIDADE E TODO SUPORTE QUE VOCÊ MERECE! DUVIDAS SOBRE INSTALAÇÃO ? TEMOS EXCLUSIVO CANAL - CENTRO de APOIO TÉCNICO AGORA CLIQUE EM COMPRAR ou se tiver ALGUMA DÚVIDA FAÇA SUA PERGUNTA E RESPONDEREMOS RAPIDAMENTE : )', 300.0, 300.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Racks and Cargo Carrier', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mkl2zlsbv0nbc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1665097804%2F58205049390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
