INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498698256', 'Liquidificador Britânia BLQ970P Turbo 900W 220V', 'Liquidificador Britânia BLQ970P Turbo 900W 220VLiquidificador Britânia Turbo tem potência de 900W produto ideal para você que procura alto desempenho na cozinha e versatilidade para prepararvários tipos de alimentos para toda família. O copo é robusto super-resistente com capacidade total de 2,6L. Conta com 4 velocidades mais a função Pulsar, assim você escolhe a velocidade ideal para preparo de açaí, vitaminas, mousses, smoothies e muito mais. E ainda acompanha filtro para coar sucos ou molhos separando a semente e o bagaço. Principais Características - 4 velocidades + Função Pulsar - autolimpeza - Conjunto de facas integradas ao copo que impede vazamentos - Faca de 4 lâminas - Potência de 900W - Tampa com sobre tampa - Base antiderrapante - Porta fio. Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas. Especificações Técnicas Marca: Britânia Modelo: BLQ970P Cor: Preto Potência: 900 W Capacidade do copo: 2,65 L Velocidades: 4 Estado: Novo Função Ice: Sim Acompanha filtro: Não Material do copo: Polipropileno Função pulsar/autolimpeza: Sim Sobretampa: Sim Quantidade de lâminas: 4 Tipo das lâminas: Serrilhadas Altura do produto: 41,1 cm Largura do produto: 21,5 cm Comprimento do produto: 21 cm Peso do produto: 1,47 kg Altura com embalagem: 24,5 cm Largura com embalagem: 35 cm Comprimento com embalagem: 18,2 cm Peso com embalagem: 1,697 kg Garantia: 360 Dias', 175.9, 175.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-mbww5n60kbs784', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23498698256', NULL, NULL