INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993060438', 'Kit Jacques Janine Hair Care Curls Shampoo 450ml Condicionador 440ml Máscara Creme Hidratação 400g', 'Descubra a Linha Curls, uma coleção sofisticada e meticulosamente elaborada para atender às necessidades específicas dos cabelos cacheados. Cada produto é enriquecido com ingredientes exclusivos que proporcionam um cuidado intensivo e personalizado. Com fórmulas 100% veganas e de alto padrão, a Linha Curls garante um tratamento completo que hidrata profundamente, define os cachos e reduz o frizz, promovendo fios alinhados, saudáveis e com um movimento natural e vibrante. Transforme seus cachos e realce sua beleza com nossa seleção premium! Contém: - 01 Shampoo Hair Care Curls 450ml; - 01 Condicionador Hair Care Curls 440ml; - 01 Máscara Hair Care Curls 400g.', 89.9, 78.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7l4gqfhie6aa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23993060438', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698033471', 'Sandália Mississipi Flatform Metalizada MC562', 'Produto marca Mississipi. Sentir-se leve em cada passo ficou mais fácil com a Sandália Mississipi Flatform da coleção Priamvera/Verão 2024 que está disponível nas cores metalizado-ouro e bronze! Perfeita para mulheres que buscam estilo e praticidade no dia a dia, esse modelo combina o charme de uma sola flatform baixa com detalhes sofisticados, destaques de um calçado versátil e moderno. A sola flatform de 2 cm proporciona estabilidade ao caminhar, enquanto as tiras finas envolvem seus pés com delicadeza, proporcionando um ajuste perfeito e evitando incômodos, assim como o calce fácil, pois não possui fechamentos. o destaque fica por conta das tiras tramadas, que adicionam um toque artesanal ao seu visual, contrastando com as tiras lisas que são elegantes. Seja para um passeio no parque, um dia de compras ou um happy hour com as amigas, essa sandália te acompanha em qualquer ocasião, garantindo um look moderno e cheio de estilo. Peso: 0,525 kg Altura da sola: 2,00 cm', 119.9, 119.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8261m-mlwg7nypy6te21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23698033471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898807146', 'Sandália Campesí Anabela Marinho Feminina CE233', 'Produto marca Campesí. Prepare-se para transformar seus dias com a Sandália Campesí Anabela, o ápice do conforto e estilo para a mulher moderna. Desenvolvida para o seu dia a dia e momentos de lazer, esta sandália combina a praticidade do calce fácil, sem fechamentos, com um design elegante. As tiras em X sobre o pé, confeccionadas em material maleável e macio, se ajustam perfeitamente. a tira frontal, igualmente macia, eleva o nível de conforto, garantindo que cada passo seja uma experiência de bem-estar. Sinta a leveza e a estabilidade da sola anabela de 4,00 cm, projetada para oferecer o suporte ideal sem abrir mão da feminilidade. Com um peso de apenas 0,524 kg, esta sandália é perfeita para quem busca liberdade de movimento e conforto duradouro. o material sintético de alta qualidade, a sola em PVC e a palmilha em EVA garantem durabilidade e maciez, tornando-a a escolha inteligente para quem valoriza qualidade e bem-estar. Não perca a chance de experimentar o conforto que seus pés merecem! Eleve seu estilo de vida com a Sandália Campesí Anabela. Perfeita para um passeio no parque, um almoço com amigos ou suas atividades diárias, ela complementa qualquer look com sofisticação e praticidade. Peso: 0,524 kg Altura da sola: 4,00 cm', 183.9, 159.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-mdkaee2z7ia2b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23898807146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
