INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299238344', 'Kit 10 Lâmpada Filamento de LED Bulbo A60 4W Âmbar Bivolt Luminária Decorativa Retro Vintage', '🌟 Lâmpada de Filamento LED Bulbo A60 - Iluminação Aconchegante e Eficiente 🌟 Desfrute de uma iluminação envolvente e elegante com a Lâmpada de Filamento LED Bulbo A60. Com um design clássico e tecnologia LED avançada, esta lâmpada oferece um ambiente acolhedor em qualquer espaço. 💡 Especificações Técnicas: Potência: 4W Tensão: 85-265V AC Lúmens: 450 LM Ângulo de Abertura: 360° Fator de Potência: >0,5 Cor: BQ 2300k (Ambar) Vida Útil: 20.000 horas IRC (Índice de Reprodução de Cor): RA 75 Índice de Proteção (IP): IP20 Garantia: 1 ano Tamanho: 60 x 105 mm Peso: 6,5 gramas Cor do Material: Ambar 🏡 Iluminação Aconchegante para Qualquer Ambiente A tonalidade ambar proporciona uma atmosfera calorosa e relaxante, ideal para áreas de descanso, salas de estar, quartos e espaços de convivência. Com seu ângulo de abertura de 360°, a luz é distribuída de forma uniforme, iluminando todo o ambiente com suavidade. 💡 Eficiência Energética e Durabilidade Com baixo consumo de energia e uma vida útil longa de até 20.000 horas, esta lâmpada de filamento LED oferece uma excelente relação custo-benefício. Além disso, seu design resistente e a garantia de 1 ano garantem sua satisfação e tranquilidade. ✨ Estilo Clássico com Tecnologia Moderna O design do bulbo A60 combina perfeitamente com uma variedade de luminárias e decorações de interiores, adicionando um toque de charme vintage com os benefícios da eficiência e durabilidade dos LEDs. Transforme qualquer espaço com a Lâmpada de Filamento LED Bulbo A60 e desfrute de uma iluminação excepcionalmente agradável e econômica! 🌟', 280.0, 112.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltxyjuqkxxucc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F19299238344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52856246460', 'Kit Xixi Pode/Não Pode Educador Sanitário Para Cães UP Clean - 500mL', 'Bem Vindos a Pet Tobby *_* EDUCADOR Xixi Sim/Não O Educador Xixi Sim! Tem um odor característico de urina de cão, perceptível somente ao olfato dos animas. Pingando algumas gotinhas deste produto no banheirinho do seu pet, ele será atraído e educado naturalmente a urinar sempre no mesmo lugar, já que terá a necessidade de sobrepor o cheiro de outro cão. Ensiná-los onde é o banheiro é tarefa difícil, porém com essa gotinha mágica, além de ficar fácil, sua casa ficará protegida de surpresas indesejadas. Educador – Xixi Não! é utilizado para repelir os cães dos lugares onde não podem fazer suas necessidades fisiológicas. O produto que tem um cheiro agradável ao olfato humano, porém o oposto para com os pets, auxilia-os na construção de hábitos mais higiênicos, para que façam suas necessidades nos lugares indicados, fato que mantém a sua casa mais limpa e organizada. Quantidade: Xixi não pode! – 500 ml Xixi Sim! – 30 ml Qualquer dúvida, Não hesite em perguntar! Estamos à disposição *-*', 19.99, 16.8, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-820m9-mpp12393ufb731', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F52856246460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
