INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093630467', 'Coleção Escolinha Animada - Alfabeto', 'A "Coleção Escolinha Animada - Alfabeto" é um conjunto educativo e interativo projetado para introduzir as crianças às letras do alfabeto de forma divertida e envolvente. Este kit completo inclui 3 canetas, 5 adesivos neon, 1 lousinha e 1 livro com atividades, proporcionando uma experiência de aprendizado prática e dinâmica. As atividades lúdicas e os exercícios práticos incentivam as crianças a reconhecerem e escreverem as letras, melhorando suas habilidades linguísticas e motoras. Repleto de ilustrações coloridas e instruções claras, cada componente é pensado para tornar o processo de aprendizagem agradável e estimulante.', 29.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra15-m4rs4xpbe450bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F23093630467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
