INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399500233', 'Aparelho Jogo De Jantar Chá Pratos Porcelana Completo 20 Peças Floralis Tramontina', 'O Aparelho de Jantar Tramontina Floralis em porcelana decorada, composto por 20 peças, é a escolha ideal para quem busca um estilo rústico e singelo, com inspiração nas delicadas flores do campo. O design floral remete à simplicidade e charme de uma casa de campo, trazendo beleza e serenidade à mesa em qualquer ocasião. Produzido em porcelana tradicional da Tramontina, o aparelho de jantar combina o toque rústico com a elegância das flores, criando uma atmosfera encantadora e atemporal para suas refeições. Composto por 4 pratos rasos, 4 pratos fundos, 4 pratos de sobremesa, 4 xícaras de chá e 4 pires, o conjunto é ideal para compor uma mesa completa com charme e sofisticação. Características: Material: Porcelana de alta qualidade Design: Inspirado nas flores, com detalhes rústicos Uso: Resistente a micro-ondas e lava-louças, proporcionando praticidade Porosidade baixa: Evita a proliferação de fungos e bactérias, garantindo mais higiene Adicione um toque de beleza simples e elegante à sua mesa com o Aparelho de Jantar Floralis, e transforme qualquer refeição em um momento especial!', 409.9, 409.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rdy4-m1cry23kp4d9c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F21399500233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
