INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252117763', 'Kit 4 Pneus 165/60R14 75H RW581 Roadwing', 'Pneu ROADWING RW581 – Durabilidade e Alto Desempenho O ROADWING RW581 foi desenvolvido para oferecer segurança, resistência e excelente desempenho em diferentes condições de rodagem. Com um design robusto e tecnologia avançada, este pneu proporciona ótima aderência, estabilidade e longa vida útil, sendo ideal para quem busca confiabilidade e eficiência. Principais Benefícios do ROADWING RW581: Alta resistência ao desgaste – Composto de borracha reforçado para maior durabilidade. Estrutura robusta – Desenvolvida para suportar grandes cargas com segurança. Aderência e estabilidade aprimoradas – Melhor tração em pisos secos e molhados. Rodagem confortável e silenciosa – Menos ruído e vibração para uma condução mais agradável. Eficiência no consumo de combustível – Baixa resistência ao rolamento, proporcionando economia. O ROADWING RW581 é a escolha ideal para quem precisa de um pneu confiável, resistente e eficiente para o dia a dia. Kit 4 Pneus 165/60R14 75H RW581 Roadwing Marca: Roadwing Modelo: RW581 Aro: 14 Índice de peso (por pneu): 75 - 387kg Índice de velocidade: H - 210km/h Construção: Radial Tipo: Uso sem câmara Aplicação: Vias pavimentadas Tipo de desenho: Simétrico Lateral: Letras pretas Garanta já o seu e tenha mais segurança e desempenho!', 959.24, 959.24, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-81zvu-midimbqba7lt4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F58252117763', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
