INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251195067', 'Central Multimídia 7 Pol Android Auto Carplay Fio H-Tech HT-3625CA 2 Din Bluetooth Usb Fm Tela Full Hd', 'Central Multimídia 7 Polegadas Android Auto Carplay H-Tech HT-3625CA 2 Din Bluetooth Usb Fm Tela Full Hd O Multimídia MP5 Tela 7" Full Touch 2DIN combina tecnologia e praticidade para transformar o interior do seu carro em um centro de entretenimento moderno, oferecendo espelhamento, CarPlay e Android Auto com fio (consulte versões compatíveis) para facilitar o uso dos aplicativos do seu smartphone, além de conexões via USB, SD e AUX. Com Bluetooth integrado, permite atender chamadas e reproduzir músicas sem cabos, enquanto as 7 opções de cores de painel personalizam o visual do seu veículo. Conta ainda com entrada para câmera de ré, 1 entrada de vídeo, 2 saídas de áudio e vídeo e potência de 4x60W, garantindo qualidade de som e funcionalidade em cada viagem. O que Acompanha Central Multimídia Android H-Tech: - 1 Central Multimídia 7 Polegadas Android H-Tech - 1 Controle Remoto Especificações Técnicas: - Compatível com espelhamento, CarPlay e Android Auto conectividade com fio (Consulte versões) - Entradas: USB/SD/AUX - Bluetooth: Ligação e reprodução músicas - 7 opções de cores de painel - 1 Entrada de vídeo - 2 Saídas de áudio e vídeo - 1 Entrada para câmera de ré - Potência de saída de áudio 4x60W Importante Recomendamos que a instalação, quando aplicável, seja realizada por um profissional qualificado. Não nos responsabilizamos por danos causados por instalação ou uso incorreto do produto. As imagens são ilustrativas. O design ou embalagem do produto pode variar sem aviso prévio, mantendo sempre suas especificações técnicas originais.', 249.22, 249.22, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-8227b-mhlzsvln320y0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F758962502%2F58251195067', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263274356', 'Kit 10 Discos de Fibra para AÇO 115mm G60 G80 G120- W-MAX', 'Descrição do Produto: Disco de fibra vulcanizada com grãos abrasivos de óxido de alumínio. Desenvolvido para lixamento de aço carbono, metais ferrosos e não ferrosos e madeira. Características: - Produzido com Grãos de Óxido de Alumínio; - Excelente acabamento; - Costado em fibra vulcanizada. Aplicações: - Desbaste de cordões de solda em aços ferrosos e não ferrosos; - Desbaste de superfícies em aço carbono, metalon, madeira e outros; - Remoção de pintura e oxidações (ferrugem). PRINCIPAISVANTAGENS ; - Fibra vulcanizada de alta resistência, proporciona bom acabamento e boa durabilidade.', 24.21, 24.21, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lj-mq1tuj3iqt4ya2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1036817611%2F58263274356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
