INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56753531137', 'Sache Chá Chá Verde 13g - CHAMEL', 'O Chá Verde carrega a força de uma tradição milenar, reverenciada no Oriente como símbolo de vitalidade, leveza e clareza. Seu sabor desperta os sentidos, trazendo energia à mente e suavidade ao corpo. Mais do que uma bebida, é um ritual que atravessou gerações, lembrando que, mesmo na correria do dia, é possível encontrar vigor em um gole cheio de história. Benefícios: ✅ Sabor marcante que desperta e revigora ✅ Sensação de leveza, foco e energia ✅ Tradição milenar associada ao bem-estar ✅ Ajuda a equilibrar a rotina com um momento de pausa ✅ Aroma herbal suave e agradável ✅ Ideal para consumo diário Ficha Técnica: ✅ Produto: Chá Verde ✅ Indicação: Vitalidade, energia, foco e bem-estar ✅ Modo de preparo: Infusão em água quente ✅ Consumo ideal: Pela manhã, à tarde ou em momentos de pausa', 12.18, 12.18, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-81ztf-mily4w044xs7a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F56753531137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
