INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297784201', 'Telha Plan PVC 2,42 x 0,88 cm 06 Ondas Afort Marrom Marrom', 'Transforme seu projeto com a Telha Colonial de PVC Afort! Ideal para quem busca economia e sustentabilidade na cobertura A Telha Colonial, com 5 ondas, é a escolha inteligente para um telhado que combina funcionalidade e estilo duradouro. A Afort traz uma abordagem pioneira, combinando conforto térmico, acústico e alta resistência em um único produto. Por serem leves, são fáceis de instalar, com um encaixe simples e resistente que reduz o tempo de montagem, economizando em mão de obra e permitindo uma estrutura menos robusta. Ganhe em tempo, custo e eficiência, garantindo uma cobertura de qualidade superior, extremamente seguras, pois são classificadas como não propagadoras de fogo e não sofrem ignição, garantem uma vedação perfeita, livre de vazamentos e com menos risco de arrasto. Garantia: 5 Anos Inclinação: 0.5 Largura (cm): 88 Galvanizada: Não Espessura (mm): 1.6 Comprimento (cm): 242 Origem do Produto: Nacional Recursos Especiais: Convencional Número de Telhas por m²: 0.5 Acabamento (Construção e Acabamento): Natural Material Principal Construção e Acabamento: PVC Marca: Afort Cor: Marrom Cor do Produto: Marrom Itens Inclusos: 5 Cor Predominante: Marrom Linha ou Coleção: Ondas Tamanho do Produto: 2,42m x 0,88m Quantidade do Produto: 5', 668.65, 668.65, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-820mp-mo0evdym3ym917', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F20297784201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
