INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699203051', 'Caixa Térmica Com Alça Ergonômica 18 Litros MOR Pêssego', 'Caixa Térmica 18L Emanando toda a sua delicadeza, suavidade e elegância, a Caixa Térmica Pêssego chegou para arrancar suspiros daqueles que amam os diversos tons da cor rosa! De produção nacional, é a companheira perfeita para aventuras entre praias, noites de camping sob as estrelas, para guardar os remédios em casa, em passeios de pescaria, na concentração para a festa com os amigos ou até mesmo em longas viagens com a família. O isolamento térmico assegura a temperatura ideal, mantendo lanches e bebidas conservados aonde quer que vá. A alça versátil e a tampa com trava dão mais segurança e mobilidade ao transporte. O seu design moderno encanta e transmite beleza em qualquer ambiente, indispensável para cultivar bons momentos ao seu lado! Material: Polipropileno Cor Predominante: Rosa Capacidade: 18 litros MOR', 111.54, 72.51, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/sg-11134201-822wm-mi5vipq5ea6c2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F23699203051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
