INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592567223', 'Rolamento Semi Eixo Câmbio Ford Ecosport 2003 a 2016 - 516738 - 122901', 'Rolamento Semi Eixo Câmbio Ford Ecosport 2003 a 2016 516738 122901 (45 x 75 x 19) Rolamento é um dispositivo usado para permitir o movimento rotacional ou linear, reduzindo o atrito e o estresse. Os rolamentos reduzem o atrito através de rolo ou esferas de metal liso, que rolam sobre superfícies internas e externas igualmente lisas. Estas esferas ou rolos sustentam a carga, permitindo que o dispositivo gire suavemente.', 68.81, 68.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-823ra-moyadjo9ddse73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23592567223', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698071850', 'Cilindro Freio OPALA 1971/1978 - 50594 - CCR9273', 'Cilindro Freio OPALA 1971/1978 TRASEIRO ESQUERDO (3/4" OU 19,05mm) O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 68.1, 68.1, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbke-lmqma4wvblui69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23698071850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
