INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097497020', 'Kit 2 Shampoo Seda Ceramidas Infusão Ativa Retinol e Colágeno 325ml', 'Shampoo Seda Ceramidas Infusão Ativa Retinol e Colágeno • Shampoo com uma poderosa combinação de vitamina, óleo e proteína • Esse shampoo é indicado para cabelos sem danos a levemente danificados. Pode ser usado diariamente • Fórmula contém Retinol, conhecido por ajudar no crescimento dos fios, Ceramidas, conhecido por fortalecer o cabelo, e Colágeno, por suas propriedades hidratantes que deixam os fios alinhados e macios • Cabelos com hidratação profunda, 5x mais fortes e com brilho o dia inteiro* • Nosso shampoo com colágeno possui fórmula com ingredientes poderosos que nutre o cabelo da raiz às pontas • Shampoo Seda Ceramidas foi desenvolvido para deixar seu cabelo do jeito que você gosta. Juntas somos mais fortes! A vida é cheia de possibilidades - tenha um cabelo incrível para todas elas. Está pronta para conhecer o novo Seda? O Shampoo Seda Ceramidas com infusão ativa tem uma poderosa combinação de vitamina, óleo e proteína, desenvolvido para as necessidades do seu cabelo. A fórmula contém Retinol, conhecido por ajudar no crescimento saudável dos fios, Ceramidas, que ajudam a fortalecer o cabelo, e Colágeno com suas propriedades hidratantes que deixam os fios alinhados e macios. Nossa fórmula com ingredientes poderosos nutre o cabelo da raiz às pontas, deixando os fios até 5x mais fortes e com brilho o dia inteiro*. O Shampoo Ceramidas Seda é indicado para cabelos sem danos a levemente danificados, e o melhor é que além de dar um brilho incrível, a fórmula não deixa os seus cabelos pesados, podendo ser usado diariamente. Nossa garrafa é 100% reciclavel. Seda possui o logo PETA, o que significa que não testa seus produtos em animais. Pronta? Coloque na mão, aplique no cabelo, massageie suavemente e enxágue. Quer resultados ainda mais incríveis? Use também o Condicionador Ceramidas. Seu cabelo ficará lindo e cheiroso do jeitinho que você gosta! Juntas somos mais fortes! *com uso do Shampoo e Tratamento Condicionador Seda Ceramidas comparado com shampoo sem agentes condicionantes', 27.98, 27.98, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-81zus-mn4hu9ip105c59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21097497020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393196382', 'Vela Ignição Mitsubishi Airtrek 2003 a 2008 - 798991 - EVI518', 'Vela Ignição Mitsubishi Airtrek 2003 a 2008 798991 EVI518 2.4 16v Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 59.53, 59.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lvpr2pa025jg16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23393196382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
