INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594152193', 'Conjunto com 4 Canecas Coup Stoneware Grande Litchi 330ml', 'O Stoneware, assim como a faiança feldspática e porcelana, é um material cerâmico. O Stoneware Porto Brasil é um material inovador e sustentável, onde a combinação das melhores matérias primas naturais, unido a um processo único de queima e acabamento manual, entregam um produto com características superiores em termos de qualidade e resistência, estando em conformidade com as principais normas mundiais. Além disso, conseguimos proporcionar peças exclusivas, onde alterações de formas, relevos e variações de cores são efeitos característicos dos produtos, evidenciando assim sua originalidade e autenticidade.', 181.9, 118.24, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7ratz-mayghfqnq9k9d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242213783%2F22594152193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898994789', 'Fantasia Esqueleto Longa Infantil Verde Vibrante Com Gorro', 'Itens inclusos: 1x Macacão Longo 1x Máscara Caveira Tamanhos: P - Veste Numeração de roupa 4 a 6 anos. M - Veste Numeração de roupa 7 a 11 anos. G - Veste Numeração de roupa 12 a 14 anos. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações Técnicas Material: 100% Poliéster. Cor: Verde. Produto: Novo, na embalagem. Produto a pronta entrega! Produto Original O clássico do Halloween com um toque vibrante e muito conforto para o seu pequeno! A época de "Doces ou Travessuras" pede um visual de arrepiar, mas sem abrir mão do bem-estar da criança! A Fantasia Esqueleto Infantil Longa reinventa o clássico monstrinho com uma estampa de ossos em um tom verde vibrante sobre o fundo preto, garantindo que o seu pequeno se destaque em qualquer festinha de Halloween, Carnaval escolar ou evento temático. Este modelo foi desenhado como um macacão de pernas e mangas longas, ideal para proteger do friozinho enquanto a criança corre e brinca. O fechamento conta com uma amarração super prática nas costas (na altura da nuca), facilitando muito na hora de vestir ou tirar. Outro grande diferencial é o gorro estilo balaclava: ao contrário das máscaras de plástico duro que machucam o rosto, este gorro de tecido macio veste como uma touca, possuindo recortes perfeitos para os olhos e cobrindo até o pescoço com a estampa da caveira. E o melhor: por ser uma peça separada do macacão, a criança pode tirar o gorro a qualquer momento para comer, beber ou descansar, sem precisar despir a fantasia inteira! Kit Completo 2 em 1 Tecido leve e solto Fácil de Vestir Visual Vibrante Com amarração nas costas', 49.9, 49.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmhre3kqihadc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F19898994789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
