INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299306493', 'Eudora Impression Legend Eau De Parfum 100ml', 'Legend: Palavra que caracteriza pessoas de notoriedade que encontraram um propósito na sociedade, sendo conhecido não só pelo resultado, mas por seu legado. Impression Legend acredita que você pode chegar ainda mais longe na sua trajetória de sucesso. ﻿ Este eau de parfum masculino foi criado para o homem movido a desafios, capaz de impressionar por sua jornada de superação, deixando sua marca.​ Apresenta uma fragrância com frescor, ao combinar notas aromáticas com especiarias frias em contraste com a força da madeira de sândalo com a Sálvia e o Gengibre, assinada pelo exclusivo Segredo de Eudora. Uma fragrância amadeirada ambarada com uma embalagem proprietária, moderna e sofisticada, ideal para homens determinados a alcançarem o topo. Se prepare para o próximo desafio, pois para quem sabe onde quer chegar, desistir não é uma opção. Família Olfativa: Amadeirado Aromático Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 249.9, 249.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8260x-mjhchu8ctts13f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F22299306493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
