INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699044026', 'Sensor De Nível Boia Civic 2012 2013 2014 2015 2016', 'Descrição Produto: Sensor Nível Boia Marca/Fabricante: BOSCH APLICAÇÃO: HONDA: Civic 1.8i 16v Flex ano 2012 até 2016 Civic 2.0i FlexOne ano 2013 até 2016 Envio: Pagamentos confirmados ate as 13hs. envio no mesmo dia. Obs: Temos envio por motoboy consulte taxa. Garantia: O PRODUTO CONSTA COM 3 MESES DE GARANTIA POR DEFEITO DE FABRICAÇÃO (NOS TERMOS DA LEI Nº8.078 DE 11/09/1990) O PROCEDIMENTO PODE LEVAR ATE 30 DIAS PARA LAUDO E CONSTATAÇÃO DO DEFEITO E TROCA DO PRODUTO. NAO SERA CONCEDIDA GARANTIA NAS SEGUINTES CONDIÇOES: - O produto apresentar danos provocados por acidente de manuseio, erro de montagem, aplicação ou manutenção inadequada; - Contaminação por: oleos e derivados, particulas metalicas, arenosas ou cristalinas em excesso, etc... - Cargas excessivas e engripamento provocados por outros componentes que comprometem o funcionamento e a vida util da peça; - Violação do produto, sinais de danificação,amassados ou quebras; - Ausência de documentos para analise como: Nota Fiscal ou Pedido de compra que comprovem a data da compra e instalação. ATENÇÃO ANTES DE EFETUAR A COMPRA, VERIFIQUE SE A NUMERAÇÃO ORIGINAL DE NOSSO ANÚNCIO É IGUAL A NUMERAÇÃO ORIGINAL DE SUA PEÇA. SENDO NUMERAÇÕES COMPATÍVEIS, LHE APLICA PERFEITAMENTE. SENDO DIFERENTE, NÃO IRÁ SERVIR; CASO NÃO TENHA A NUMERAÇÃO ORIGINAL EM MÃOS, ENTRE EM CONTATO COM SUA CONCESSIONÁRIA, E SOLICITE O CÓDIGO ORIGINAL DE SUA PEÇA; PEDIMOS A GENTILEZA DA COMPREENSÃO, PRA EVITAR POSSÍVEIS TRANSTORNOS. PARA DEVOLUÇÃO DE PRODUTO, SOMENTE COM A EMBALAGEM ORIGINAL E SEM USO. Garantia do vendedor: 3 meses', 135.0, 135.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-8258v-