INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897489405', 'Tênis Oxto Reason 2 Feminino Esportivo', 'Tênis Oxto Reason 2 Feminino O modelo Reason 2, e o mais novo modelo da Oxto, que garante conforto durante suas atividades do dia a dia. Confeccionado em mesh, garantindo conforto e respirabilidade do calçado, sua entressola e solado garante conforto e aderência, tração e durabilidade do tênis. Garanta já o seu Destaque de produto: Cabedal: Mesh. Lingueta: Macia e flexível. Palmilha: EVA. Forro Têxtil: Interno e acolchoado reforçado, para maior segurança e conforto. Solado: Borracha. Ajuste: Cadarço Indicação de uso: Corrida – Caminhada Tipo de pisada: Neutra. Dicas de Conservação: Utilizar o calçado de acordo com a sua modalidade (Running, Casual, Adventure, Society ou Indoor). Dicas de Limpeza: Utilizar um pano levemente umedecido e secar à sombra. Não lavar à maquina, pois poderá destruir ou danificar as fibras do calçado.', 129.9, 129.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv0ghka08lfz3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764630431%2F22897489405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492498685', 'Desodorante Creme Herbissimo Fresh 55g', 'O Desodorante Creme Herbíssimo Fresh, conta com fórmula reconhecida pela sua eficácia e conforto, seu uso ajuda evitar a transpiração da área e ainda tem um cheiro delicioso e inconfundível, que já é tradição da marca, com notas verdes, frescas e energizantes. Modo de uso: Aplique leve camada nas axilas. Espere secar bem antes de se vestir. #html-body [data-pb-style="646BA64F8E3E3"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64F8E3F8"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 22.2, 22.2, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rbk5-lmgfrn56w3fd5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23492498685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
