INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898504750', 'Bola Campo Uhlsport Tamanho 5 Oficial Original Sintético Profissional Adulto Juvenil Brasileirão', 'CARACTERÍSTICAS: Material Externo: Micro Composite com microcélulas sintéticas Câmara Interna: Látex injetado com tecnologia AIRTEC Peso: 410–450g Circunferência: 68–70 cm Tecnologias: Aerotrack, + Glue, Multi Axial, Intracel Miolo: Removível em silicone anti-ressecamento A Bola de Futebol Uhlsport Match R2 é a réplica oficial do Campeonato Brasileiro 2024, desenvolvida para oferecer desempenho superior em jogos de campo. Sua construção com materiais de alta qualidade garante durabilidade e performance excepcionais. Com câmara de látex injetado e forro com fios sintéticos, proporciona excelente retenção de ar e equilíbrio. A camada interna de EVA de 2.5mm oferece conforto e absorção de impacto, enquanto o revestimento externo em microcélulas sintéticas assegura resistência e precisão nos chutes. A tecnologia de termocolagem +GLUE evita absorção de água, e o sistema AEROTRACK melhora a trajetória da bola em até 30%, garantindo jogadas mais precisas e eficazes. BENEFÍCIOS: Durabilidade: Materiais de alta qualidade que resistem ao desgaste Precisão: Trajetória aprimorada com tecnologia AEROTRACK Conforto: Amortecimento eficiente com camada de EVA de 2.5mm DIFERENCIAIS TÉCNICOS: Tecnologia AIRTEC: Câmara de látex injetado que proporciona equilíbrio total e excelente retenção de ar O QUE ESTÁ INCLUSO? 1 Bola de Futebol Uhlsport Match R2 O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes.', 256.45, 139.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Volleyball', 'https://cf.shopee.com.br/file/br-11134207-820lk-mn60zq1x7daad3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F23898504750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597920745', 'Espelho Orgânico Premium 55x85cm Decorativo Grande Retangular Quarto Banheiro', 'IMPORTANTE: MANDAMOS O ESPELHO MUITO BEM EMBALADO, EM CAIXA REFORÇADA COM ALERTAS DE FRÁGIL E AMPLAS PROTEÇÕES DE ISOPOR POR DENTRO, ASSEGURANDO CONTRA QUEBRAS E TRINCOS! O Espelho Orgânico Premium 55x85cm é a escolha ideal para quem busca um ambiente mais moderno, elegante e sofisticado. Seu formato orgânico proporciona um visual contemporâneo que valoriza a decoração e cria um ponto de destaque em qualquer espaço. Com tamanho amplo, é perfeito para salas, quartos, banheiros, lavabos, closets, halls de entrada e ambientes comerciais, oferecendo funcionalidade e beleza no dia a dia. ⭐ Destaques ✅ Design orgânico moderno e sofisticado ✅ Tamanho grande para maior destaque na decoração ✅ Ajuda a ampliar visualmente os ambientes ✅ Contribui para uma sensação maior de luminosidade ✅ Ideal para quartos, banheiros, salas e closets ✅ Combina com estilos modernos, minimalistas e contemporâneos ✅ Excelente opção para decoração e uso funcional diário ⚙️ Informações do produto Produto: Espelho Decorativo Modelo: Premium Formato: Orgânico Tamanho: 55cm x 85cm Material: Vidro Tipo de Fixação: Suporte pendurador para parafuso Instalação: Parede Estilo: Moderno / Contemporâneo Indicação de uso: Sala, quarto, banheiro, lavabo, closet, hall de entrada e escritório Função: Decoração e uso diário ❓ Dúvidas Frequentes Como é feita a instalação? → O espelho possui suporte pendurador para fixação com parafuso na parede. Pode ser instalado no banheiro? → Sim, é indicado para banheiros, lavabos e demais ambientes internos. Serve para quarto e closet? → Sim, é uma excelente opção para quartos, closets e áreas de cuidados pessoais. O formato orgânico está em alta na decoração? → Sim, os espelhos orgânicos são tendência em projetos modernos e contemporâneos. Ajuda a ampliar o ambiente? → Sim, os espelhos proporcionam maior sensação visual de amplitude e luminosidade. Pode usar todos os dias? → Sim, é indicado para uso diário normal. 👉 Garanta já o seu com envio rápido e compra segura pela Shopee. 💬 Qualquer dúvida, estamos à disposição no chat.', 209.9, 129.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-820lq-mqc8m9dlg1du8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410522123%2F21597920745', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
