INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41274778692', 'Whey Turbo Refil - Sabores 907g - Black Skull', 'INFORMAÇÃO NUTRICIONAL Suplemento Alimentar em Pó Whey Protein Concentrado Sabor Morango, Chocolate e Baunilha Contém 907g DESCRIÇÃO O Whey Turbo™ da Black Skull USA™ é um suplemento alimentar em pó com os sabores de baunilha, chocolate ou morango, formulado com proteína concentrada do soro do leite e maltodextrina. Cada porção fornece 30 g de proteína, podendo ser utilizada em diversas preparações de acordo com sua rotina alimentar. INGREDIENTES BAUNILHA: Proteína concentrada do soro do leite, maltodextrina, saborizante e edulcorante sucralose. ALÉRGICOS: Contém lactose. Não contém glúten. Produtos em refil não acompanham scoop medidor. CHOCOLATE: Proteína concentrada do soro do leite, maltodextrina, cacau em pó, saborizante e edulcorante sucralose. ALÉRGICOS: Contém lactose. Não contém glúten. Produtos em refil não acompanham scoop medidor. MORANGO: Proteína concentrada do soro do leite, maltodextrina, saborizante, corante vermelho de beterraba, acidulante ácido cítrico e edulcorante sucralose. ALÉRGICOS: Contém lactose. Não contém glúten. Produtos em refil não acompanham scoop medidor. MODO DE USO Misturar (120 g) em 150 a 200 ml de água, uma vez ao dia ou conforme recomendação de médico ou nutricionista. ARMAZENAMENTO Conservar em local fresco, seco e ao abrigo da luz. Após aberto, consumir preferencialmente em até 30 dias. RECOMENDAÇÃO Produto destinado a adultos (=19 anos). O consumo deve estar associado a uma alimentação equilibrada e hábitos de vida saudáveis.', 90.0, 90.0, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mfxzz80fmyobed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F41274778692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
