INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11947604913', 'Meia HUPI 5K Preto - LT para pés menores 34-38', 'Meia para ciclismo e corrida! Conforto, design, tecnologia e qualidade são adjetivos que descrevem perfeitamente as meias HUPI. Testado e aprovado por atletas de diversas modalidades, a meia HUPI é um item indispensável para você. Praticar esportes com conforto e máximo desempenho é o seu objetivo, e também o nosso. Por isso a meia HUPI apresenta diversos destaques que fazem dela um item fundamental. O material utilizado na fabricação da meia é importado da Alemanha. Os fios de elastano e poliamida formam um conjunto cheio de vantagens. O principal destaque é o conforto, proporcionado pela transpiração que a meia oferece, deixando os pés secos e bem protegidos. A combinação da matéria prima assegura a flexibilidade oferecendo maior liberdade de movimento, sem que a peça laceie, perdendo sustentação. Na região dos dedos e calcanhar, os fios são dispostos em direções diferentes do restante da meia, fazendo com que a modelagem se torne muito mais anatômica, acompanhando o desenho dos pés. Esta característica também prolonga a durabilidade, impedindo o desgaste. Características: * Cano médio de 15 cm; * Composição: 95% Poliamida | 5% Elastano; * Conteúdo: 1 par * Tamanho único: Veste do 34 ao 38 ATENÇÃO: As cores podem apresentar diferenças em tonalidade conforme a calibragem do monitor.', 74.28, 69.9, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/br-11134207-820lj-mls560620kxyf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F11947604913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258167414', 'realme Note 60X 3+64GB Smartphone Celular Versão Global Bateria 5000mAh Câmera 8MP NFCTela 6,74 90Hz Verde', 'Note 60x – Bateria Potente, Design Robusto e Desempenho Inteligente O Note 60x é um smartphone ideal para quem busca praticidade no dia a dia com estilo e resistência. Equipado com uma bateria de longa duração, tela com taxa de atualização de 90Hz e estrutura reforçada com proteção IP54, ele entrega desempenho confiável, visual moderno e excelente custo-benefício. Destaques do Produto Processador Unisoc T612 Octa-Core – fluidez para tarefas cotidianas Tela de 6.74" HD+ com 90Hz – mais conforto visual e navegação suave Bateria de 5000mAh – autonomia para o dia todo com carregamento USB-C 4GB RAM + até 8GB de RAM virtual – mais velocidade e estabilidade Armazenamento de 64GB com expansão até 2TB via microSD Câmera traseira de 8MP e frontal de 5MP – registros simples e funcionais Proteção IP54 – resistente a respingos e poeira Leitor de digital lateral + desbloqueio facial Entrada P2 para fone de ouvido Bluetooth 5.0, Wi-Fi 5GHz, GPS, Dual SIM Sistema operacional baseado em Android 14 Especificações Técnicas Processador: Unisoc T612 Octa-Core (12nm) Memória RAM: 4GB + até 8GB via RAM virtual Armazenamento: 64GB (expansível até 2TB com microSD) Tela: 6.74” LCD HD+ (1600x720), 90Hz, até 560 nits Câmera Traseira: 8MP Câmera Frontal: 5MP Bateria: 5000mAh com carregamento de 10W via USB-C Conectividade: Wi-Fi 5, Bluetooth 5.0, GPS, entrada P2 Resistência: Certificação IP54 – proteção contra respingos e poeira Sistema Operacional: Android 14 Segurança: Desbloqueio facial + leitor de digitais lateral Dimensões: 167,3 x 76,7 x 7,84mm Peso: 187g Conteúdo da Embalagem Smartphone Note 60x Cabo USB-C Capa protetora Ferramenta de ejeção do SIM Manual do usuário Protetor de tela (instalado de fábrica) Envio Ultra Rápido com logística ️ Suporte Especial! Acompanha nota fiscal e suporte via chat antes e após a compra. Em caso de qualquer dúvida ou problema, fale conosco antes de avaliar – resolvemos com prioridade total! Palavras-chave em alta para busca: smartphone resistente, celular com ip54, celular com 90hz, celular com bateria 5000mah, celular android 14, celular bom e barato, celular com desbloqueio facial, celular com entrada p2, celular para o dia a dia, celular com expansão de ram, celular custo-benefício, smartphone em promoção, smartphone 4gb, smartphone 64gb, smartphone com leitor lateral, celular de trabalho, celular simples potente', 799.0, 799.0, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/br-11134207-820lh-mml4jsrrmt52dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1764902257%2F58258167414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492631502', 'GLACO 75ML Repelente de Chuva Cristalizador de Para Brisas Hidrorepelencia Repele Agua Repelencia', '01 - GLACO 75ML GLACO Características: Glaco é um super repelente de água que melhora consideravelmente a visão do Motorista. Em velocidade acima de 45 km/h a alta repelência do Glaco entra em ação, proporcionando uma visibilidade perfeita mesmo sob fortes chuvas, aumentando consideravelmente a segurança; Em muitos casos dispensa o uso do limpador de para-brisas; Não mancha a pintura; Utilizar somente do lado externo; PASSO 1 Lave bem o vidro ou para-brisa com shampoo ou detergente para remover sujeira e a oleosidade; Seque bem com um pano limpo e macio; Abra o Glaco e coloque-o sob o vidro a ser tratado. O produto começará a sair lentamente. Aperte o Frasco se necessário. PASSO 2 Faça a aplicação de modo uniforme sobre todo o vidro em movimentos circulares ou retos sem deixar Falhas. Para Melhor visibilidade, utilize em todos os vidros do veículo; PASSO 3 Espere secar de 10 a 15 a minutos. Utilize toalhas de algodão macio, como a New Body Towel da SOFT99, a toalha deve estar seca e limpa para remover o excesso; Não utilize toalhas de micro fibra, pois este material possui características que absorvem muito liquido A repelência à água é surpreendente. Acima de 45 km/h, a chuva é repelida proporcionando maior segurança e visibilidade. Utilize o mínimo possível o limpador, pois ele pode remover o produto aos poucos reduzindo a repelência; Para manter maior repelência, utilize o GLACO WASHER SOFT99 no reservatório com a água do esguicho.', 69.9, 69.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lo70dotzgf2f19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F319801107%2F23492631502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
