INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14787685120', 'Cera Cristalizadora Wax Finish Perola 100g', '- Bem vindos a Atlanta Auto Peças & Acessórios. Somos uma empresa pioneira com mais de 30 anos no mercado de auto-peças. Com 5 excelentes lojas. ======================================================================= Modo de uso: Lave e enxugue bem o veículo, não aplique ao sol ou em superfícies quentes, use somente na sombra. Aplique manualmente com o aplicador espalhe uniformemente a mínima quantidade possível em movimentos circulares, pequenas partes por vez. Ex. Capô, teto ( 4 partes), portas laterais, para –lama ( 3 partes). Deixe secar por alguns segundos para o solvente evaporar, limpe com toalha de microfibra seca todo o veiculo. Se notar pequenas névoas é excesso de cera. Umedeça um pano macio ( bem Torcido) passe sobre o auto e imediatamente notará um brilho maravilhoso. Embalagem: 01 Cera Cristalizadora Wax Finish Perola 100g Códigodo Fabricante: 050501 CodBarras:7896067722077', 55.56, 55.56, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/72686e40fa1b7c9c283959a3f404a872', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F779076938%2F14787685120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
