INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998926393', 'Condicionador Manutenção para Cachos Vector Force Grandha 980ml', 'VECTOR FORCE CONDITIONER O Vector Force Conditioner é um condicionador especial para cabelos cacheados e crespos que combina a reposição lipídica dos óleos vegetais de jojoba, avelã e macadâmia com o toque delicado dos óleos essenciais de pimenta rosa, ylang ylang e anis estrelado e é carreado pelo óleo vegetal ozonizado de girassol, com precursores de 18-MEA para o fortalecimento capilar. Um sistema de condicionamento exclusivo para melhorar o controle e a definição dos cabelos crespos e cacheados. Prioriza a leveza e o conforto dos ativos naturais, assim como uma experiência olfativa única e uma formulação repleta de benefícios para o cuidado exclusivo de preservação de ondas e cachos. Fórmula vegana com foco nos princípios da sustentabilidade e aplicações inteligentes da fitoterapia cosmética. MODO DE USO Após lavar os cabelos com o Vector Force Shampoo, aplique o Vector Force Conditioner nos cabelos molhados e massageie-os delicadamente mecha a mecha, até o total desembaraço manual dos fios, sem auxílio de pente ou escova. Remova o excesso de produto com uma toalha. Seque os cabelos com auxílio de um secador com difusor em temperatura e potência médias. INFORMAÇÕES IMPORTANTES Não testado em animais. Dermatologicamente testado. Produto vegano. Contém 3 óleos vegetais (jojoba, avelã e macadâmia), 3 óleos essenciais (pimenta rosa, ylang ylang e anis estrelado) e óleo vegetal ozonizado de girassol. Garantia do vendedor: 90 dias Quem somos : A Locus é uma loja online, que oferece produtos nacionais e importados no Brasil. , temos orgulho desse sucesso e hoje conquistamos clientes em todo o Brasil, o resultado para nosso sucesso é simples, entregamos exatamente o que prometemos para atender todas as expectativas dos nossos clientes. Servir bem, para servir sempre. Obrigada!!!', 335.79, 335.79, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-824hk-mf01enbahx5740', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1535613525%2F22998926393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
