INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498345429', 'FILTRO DE AR BMW MOTORRAD G310 2017 2018 2019 2020 2021 2022 2023 2024 FILTRAN', 'Código do produto: 2051459 Marca: FILTRAN O Filtro de Ar FILTRAN MODELO BMW é uma peça crítica para o desempenho e a durabilidade do motor da motocicleta. Ele desempenha um papel vital na filtragem de impurezas do ar, garantindo um funcionamento eficiente do motor e protegendo-o contra danos. Manter o filtro de ar limpo e em boas condições é essencial para manter a performance da moto e prolongar a vida útil do motor. Filtro de AR Modelo Original FILTRAN. APLICAÇÃO: BMW G310r 2017 2018 2019 2020 2021 2022 2023 2024 MEDIDA APROXIMADA: -ALTURA: 44 MM -COMPRIMENTO: 102 MM -LARGURA: 86 MM NÃO ACEITAMOS DEVOLUÇÕES DE PRODUTOS QUE JÁ FORAM MONTADOS E/OU USADOS. - Instalação- De extrema importância que o produto seja instalado nas fixações originais da moto e por um mecânico profissional – EVITAR ADAPTAÇÕES. - Todas as garantias são dadas pelos fabricantes, e variam de produto para produto. Caso tenha alguma dúvida, entre em contato conosco. - Para devoluções, os produtos deverão ser remetidos em suas embalagens originais. - Certifique-se de preencher corretamente seus dados pessoais e endereço para que não haja problemas com o pedido. - Produto Novo - Enviamos para todo o Brasil. - Imagem meramente ilustrativa - Tire todas as dúvidas antes da compra. - Evite transtornos!!!!!!!!!!!!!', 33.9, 33.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd4k-m7te0jehwix36b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F22498345429', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797309085', 'Pneu Pirelli 110/90-17 Xre 190 Bros 150 Bros 160 60p uso com camara Mt60 Pirelli + Camara', 'anuncio contem: -1 pneu mt 60 110/90-17 -1 camara aro 17 INFORMACOES SOBRE O PNEU Marca: PIRELLI Modelo: MT60 Medida: 110/90-17 Largura: 110mm Perfil: 90 Aro: 17 Índice de peso: 60-250 kg Índice de velocidade: P-150 km/h Posição no Veículo: Traseiro Tipo de Montagem: COM CÂMARA ALGUMAS APLICACOES: FLY 150, FLY 250; CROSSER S ABS, CROSSER Z ABS, XTZ 150 CROSSER; SHI 175, XY 150 GY, XY 150 GY EXPLORER; NK 150; NXR 125 BROS, NXR 125 BROS FLEX, NXR 150 BROS, NXR 150 BROS FLEX, NXR 150 BROS MIX, NXR 160 BROS FLEX, XRE 190. OBSERVAÇÕES: Não informamos e nem enviamos um DOT específico de pneu. Temos uma grande quantidade de pneus em estoque e um alto fluxo de pedidos diários que impossibilita o envio de um pneu com DOT específico. Todos os nossos produtos possueM fabricação recente, são novos, originais e ACOMPANHA NF. Produto novo. Garantia: 5 anos Contra Defeito de Fabricação ( FABRICANTE ) ATENCAO !! Garantia de 5 anos somente por defeitos de fabricação, ficando inválida em caso de danos por acidentes, buracos na pista, mau uso e ainda má instalação. É necessário e indispensável instalar o pneu com um profissional especializado. Em relação a trocas e/ou devoluções, salientamos que deve observar o prazo para realizar a mesma. Os itens devem estar obrigatoriamente, no mesmo estado em que recebeu e com suas etiquetas. ( CONFIRA AS MEDIDAS NO MANUAL DO VEICULO! NAO NOS RESPONSABILIZAMOS POR ADAPTAÇOES! ) NÃO ACEITAMOS DEVOLUÇÕES DE PRODUTOS QUE JÁ FORAM MONTADOS E/OU USADOS. - Instalação- De extrema importância que o produto seja instalado nas fixações originais da moto e por um mecânico profissional - EVITAR ADAPTAÇÕES. - Todas as garantias são dadas pelos fabricantes, e variam de produto para produto. Caso tenha alguma dúvida, entre em contato conosco. - Para devoluções, os produtos deverão ser remetidos em suas embalagens originais. - Certifique-se de preencher corretamente seus dados pessoais e endereço para que não haja problemas com o pedido. - Produto Novo - Enviamos para todo o Brasil. - Todos nosso produtos acompanham Nota Fiscal! - Tire TODAS as dúvidas antes da compra - IMAGENS ILUSTRATIVAS - EVITE TRANSTORNOS!', 512.0, 460.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-820l5-mqq7kodrpjwh60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F22797309085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
