INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260952649', 'Slide Melissa Comfy Slim - 38070', '✨ Casa das Três Meninas – A sua casa cor-de-rosa. ✨ Há mais de 22 anos no mercado, somos revendedores oficiais da Melissa, com loja física e online. Agora também na Shopee, levamos o estilo, o conforto e a originalidade da Melissa até você com muito carinho e confiança! 🔎 DÚVIDAS FREQUENTES 1. Os produtos são originais? Sim! Trabalhamos exclusivamente com produtos 100% originais. Somos revendedores autorizados da Grendene, fabricante oficial da Melissa. 2. O produto vai na caixa original? Sim! Todos os calçados são enviados na caixa original da Melissa. Atenção: Os modelos mais recentes não acompanham o saquinho de TNT. 3. Acompanha nota fiscal? Sim, emitimos nota fiscal para todos os pedidos. Ela é enviada por e-mail. 4. Posso trocar o produto? A Shopee permite devolução gratuita dentro do prazo informado na plataforma. Para realizar uma troca, basta devolver o item e fazer um novo pedido com o tamanho/modelo desejado. 5. Tem garantia? Sim! Todos os produtos Melissa possuem garantia de 90 dias (3 meses) oferecida pela própria fabricante. 📦 Observação: A caixa pode apresentar pequenas marcas ou amassados durante o transporte, mas garantimos que o produto será embalado com muito cuidado. 👣 DICA: Consulte a tabela de medidas em centímetros disponível na descrição de cada modelo para escolher o tamanho ideal. Com carinho, Equipe Casa das Três Meninas 💕', 219.9, 219.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-820lt-mofjeesuf7y807', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1571997239%2F58260952649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594418513', 'Par Bandeja Balança Dianteira Esquerda Direita March Versa', 'Sobre nós: A ACS AUTO é uma loja especializada em peças automotivas nacionais e importadas. Com mais de 35 anos de experiência no ramo automotivo procuramos sempre oferecer um serviço de qualidade e eficiência para os nossos clientes. Estamos sempre a disposição para quaisquer dúvidas! 01 (Um) Balança lado direito com Pivo; 01 (Um) Balança Lado esquerdo com Pivo; Código do produto: BDJ2045 BDJ2046; Aplicação dos Veículos: Montadora: Nissan; Veículo: March; Motor: 1.0, 1.6; Ano: 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020. Montadora: Nissan; Veículo: Versa; Motor: 1.0, 1.6; Ano: 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020. Sobre Fabricante; A Perfect Automotive é especializada na produção de peças para sistemas de direção e suspensão, oferecendo componentes como barras axiais, terminais de direção e braços de suspensão, conhecidos pela qualidade e confiabilidade. A bandeja de suspensão (ou braço de suspensão) conecta o chassi ao conjunto de rodas, permitindo o movimento vertical das rodas, absorvendo impactos e mantendo o alinhamento e a estabilidade durante a condução. Principais funções: Conectar o chassi às rodas, garantindo estabilidade. Manter o alinhamento das rodas e melhorar o controle. Absorver impactos e proporcionar conforto. Garantir estabilidade em curvas. Boas práticas de uso e manutenção: Inspeção periódica para detectar desgaste. Substituição de peças danificadas. Evitar impactos severos. Realizar alinhamento e balanceamento após substituições.', 461.22, 461.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meu3e0d1ua6a0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632973355%2F23594418513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
