INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194225283', 'Mini Processador De Alimentos Britânia 360ml Função Pulsar 2P 110V', 'Mini Processador De Alimentos Britânia 360ml Função Pulsar 2P 110VCom o Mini Processador de Alimentos Britânia 2P é possível triturar alimentos com facilidade em apenas um toque. A lâmina em aço inoxidável é resistente e durável, perfeita para triturar alimentos com precisão e eficiência. Além disso, sua jarra com capacidade para 360ml é transparente, permitindo observar os alimentos e controlar o grau de trituração de diversas receitas gostosas. Esse Mini Processador de Alimentos possui ainda trava de e função pulsar para ajudar no processamento de nozes, coco, torradas, carne, cebola, entre outros. Sua vida ainda mais prática com o Mini Processador da Britânia! Principais Características - Trava de : o aparelho só funciona com a jarra/copo encaixados na posição correta - Tritura os alimentos com apenas um toque - Jarra transparente com capacidade para 360 ml - Permite visualizar o processo e a quantidade preparada - Lâmina em aço inoxidável - Função Pulsar - Composição: Plástico e metal - Potência de 160W Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas; # Especificações Técnicas Marca: Britânia Modelo: Mini 2P Cor: Preto Estado: Possui trava de : Sim Funcionamento: O aparelho só funciona com a jarra/copo encaixados na posição correta Altura do produto: 14,6 cm Largura do produto: 20 cm Comprimento do produto: 10,5 cm Peso do produto: 0,686 kg Altura com embalagem: 15,7 cm Largura com embalagem: 21,5 cm Comprimento com embalagem: 12,3 cm Peso com embalagem: 0,792 kg Garantia: 360 Dias', 186.9, 186.9, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-mc7vy01rp5x341', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23194225283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
