INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892317239', 'Bíblia de Estudo Da Mulher de Deus - Luxo - Falas de Jesus em Realce - Com índice', 'Está bíblia oferece vários elementos úteis para o estudo e a devoção, salienta os temas príncipais Inclui esboços de personagens de mais de 100 mulheres mencionadas pelo nome ou não na bíblia A Bíblia da Mulher de Deus, nos convida a perguntar o que significa ser fiel em nossa época Contém também mapas, tabelas e ilustrações para facilitar a localização geografica, histórica e visual das narrativas ESPECIFICAÇÃO DO PRODUTO * Editora Kings cross *Titulo: Bíblia da Mulher de Deus *Falas de Jesus em Destaque *Promessas de Deus para mulheres *1354 Estudos e Comentários *Tradução Almeida Revista e corrigida *Tamanho da Letra Grande *Idioma Português *Acabamento Capa Flexível *Medida 18,5 x 24,5 cm *Páginas 1660 *Possuí índice *Peso 1,185 kg * Possuí Harpa Pentecostal com 696 hinos e Texto Colorido *Índice das mulheres mencionadas pelo nome *Índice das mulheres não mencionadas pelo nome *Índice dos artigos (Alfabético) *Índice dos artigos (Ordem dos Livros) *Índice dos mapas, tabelas e ilustrações *Plano de leitura paronâmica da bíblia em um mês *Plano de leitura do novo testamento em 90 dias *Plano de Leitura da bíblia em um ano *Promessa para mulheres (Edição em Português) *Promessas por livro (Edição em Português) *Promessas por temas (Edição em Português)', 94.99, 85.5, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln2z0zftl1x7a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F23892317239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
