INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19557811371', 'Tênis Casual Masculino Couro Ferracini Fechamento Cadarço Impulse Preto 7613-570A', 'ATENÇÃO: ESSE MODELO RECOMENDAMOS COMPRAR UMA NUMERAÇÃO MENOR QUE A HABITUAL, POIS A FORMA É GRANDE! O sneaker masculino Ferracini Impulse Preto traz um design moderno, sofisticado e atemporal. Com sua construção totalmente preta, ele se torna uma escolha versátil para quem busca um calçado que combine com qualquer look. Inspirado no conceito athleisure, esse modelo transita entre estilos casuais e formais, podendo ser usado com jeans, camisetas e até peças de alfaiataria. O solado em caixa alta desse sneaker Ferracini adiciona um toque fashion ao visual, além de proporcionar máximo conforto e estabilidade ao caminhar. Ideal para o dia a dia ou ocasiões especiais, o sneaker masculino Impulse Preto complementa qualquer produção com elegância e funcionalidade. Se você procura um tênis que une design, conforto e versatilidade, esse é o modelo ideal. FICHA TÉCNICA Cabedal: Couro Palmilha: P.U. forrada em couro Solado: P.U. Cadarço: Convencional (De amarração) ALTURA DO SOLADO Frente: 2cm Traseira: 5cm Guia de medidas: (MEDIDAS DA PALMILHA EM CENTÍMETROS) 37 -26 38 - 27,5 39 - 27,5 40 - 28 41 - 29 42 - 29,5 43 -30,5 44 - 31 Se você possui um sapato com a palmilha removível, o processo é bem simples. Pegue uma régua ou uma fita métrica e meça do calcanhar a ponta da palmilha. Com esse número em mãos, basta comparar com a tabela acima.', 519.9, 519.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx7-mbt5y3f6i7nyb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733934100%2F19557811371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12544283694', 'Shampoo Aussie Bye Bye Frizz Maciez e Brilho 360ml', 'O Shampoo Aussie Bye Bye Frizz dá uma aula de disciplina nos seus fios mais rebeldes, transformando o frizz em um cabelo cheio de brilho e maciez. Ele ainda deixa o cabelo com aquele cheirinho de Aussie que todo mundo ama. - Mostre para o frizz quem manda aqui! Cabelo hidratado e sem frizz, para você não parar de curtir. - Aussie hidrata mais do que uma marca líder em perfumaria*. - Fórmula dos Estados Unidos e inspirada na Austrália. - Com Babosa Australiana e Óleo de Jojoba. - 100% livre de parabenos, petrolatos e corantes. - Vegano e Cruelty Free. Dicas para um efeito maravilhAussie: 1. Lave bem o seu cabelo com o Shampoo Aussie Bye Bye Frizz. Repita até que sinta seu cabelo totalmente limpo. 2. Tire o excesso de água do cabelo. Se precisar, use uma toalha macia e seca. 3. Aplique o 3 Minutos Milagrosos Aussie Bye Bye Frizz, deixe agir por 3 minutos e enxágue. 4. Aplique o Condicionador Aussie Bye Bye Frizz para selar as cutículas e enxágue. 5. Aplique o Spray Leave-In Aussie Bye Bye Frizz e curta o cabelo mais macio e brilhoso. Óleo de Jojoba e Babosa Australiana. Anti Frizz. Brilho e maciez. 100% livre de parabenos, petrolatos e corantes. Shampoo Vegano e livre de crueldade animal. *Marca entre as 3 mais vendidas em perfumarias identificada de acordo com Euromonitor International Limited; Cuidados para o Cabelos é a agregação de shampoos, condicionadores, agentes de modelagem, tratamentos contra a queda de cabelo, produtos 2 em 1, permanentes e relaxantes, colorantes e cuidados profissionais do tipo salão de beleza. Perfumarias inclui lojas cuja atividade principal seja a venda de produtos cosméticos, de toalete ou de higiene pessoal. Vendas no ano de 2020 em volume (unidades vendidas).', 65.09, 65.09, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/66a7fc6b80b220ecf4a040d20d2a711b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F12544283694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
