INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899256591', 'Solapa Grande (Pct com 10 temas diferentes) – Histórias Clássicas para Ler e Colorir', 'Venha conhecer histórias cativantes com ilustrações encantadoras! Com Clássicos para ler e colorir, você terá dez livros incríveis para conhecer ainda mais os personagens encantadores de todos os tempos. Cachinhos Dourados, O patinho feio, O mágico de Oz, Alice no país das maravilhas, A galinha dos ovos de ouro, João e Maria, Os três porquinhos, Chapeuzinho vermelho, O soldadinho de chumbo e O gato de botas esperam por você para que solte a criatividade com as cores. A diversão é aqui, com a Bicho Esperto.', 18.9, 18.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6k-lv53v7f1hobf6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F18899256591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
