INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193567424', 'Bolsa de Ferramentas Profissional 16 Bolsos com Fundo Reforçado até 30kg - Pró Euro', 'Bolsa Maleta para Ferramentas Pró Euro – 16 Bolsos, Fundo Reforçado e Alta Resistência A Bolsa de Ferramentas Pró Euro foi desenvolvida para profissionais que precisam de organização, resistência e praticidade no dia a dia. Com 16 bolsos estrategicamente distribuídos, oferece espaço ideal para armazenar ferramentas manuais, elétricas e acessórios, mantendo tudo organizado e de fácil acesso. Seu fundo reforçado garante maior durabilidade e suporta ferramentas mais pesadas, tornando a bolsa ideal para uso intenso em obras, oficinas e serviços externos. Principais Características 16 bolsos no total: 8 internos e 8 externos (3 com fechamento e 5 abertos) Fundo reforçado para maior resistência Material durável para uso profissional Grande capacidade interna Organização prática e eficiente Benefícios Mais produtividade no trabalho Fácil acesso às ferramentas Transporte seguro e confortável Alta durabilidade mesmo em uso intenso Excelente custo-benefício Conforto no Transporte Alça de mão reforçada com punho Alça de ombro ajustável até 1,20 m Ideal para transporte em longos períodos Indicada para: Eletricistas Encanadores Marceneiros Montadores de móveis Técnicos de manutenção Construção civil em geral Especificações Técnicas Capacidade de carga: até 30 kg Dimensões (A x C x L): 33 cm x 47cm x 23 cm Ideal para quem busca uma bolsa resistente, espaçosa e funcional, perfeita para organização profissional no dia a dia. Garantia: 3 meses', 189.9, 149.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3awxmewy57fab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421509827%2F23193567424', NULL, NU