INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202521868', 'Jogo De Tapete Automotivo Bandeja De Borracha Para Carro BYD Seal Cabine e Porta-Malas 3D Ekap', 'Conjunto Tapete Automotivo de Bandeja em Borracha com Borda BYD Seal Cabine e Porta-Malas Ekap Mantenha seu carro sempre limpo e protegido com o tapete bandeja. Desenvolvido para oferecer máxima resistência e praticidade, este tapete é a escolha ideal para motoristas que buscam comodidade na limpeza, conforto e usabilidade. - Proteção total: Design tipo bandeja com bordas elevadas que evitam o acúmulo de sujeira, lama e líquidos no carpete do carro. - Durabilidade extrema: Fabricado em borracha de alta qualidade, resistente ao desgaste e às variações climáticas. - Fácil limpeza: Basta remover e lavar com água e sabão para mantê-lo sempre como novo. - Aderência: Superfície texturizada que evita o deslizamento dos pés, proporcionando mais segurança na direção. - Encaixe Perfeito: garantindo encaixe ideal e estabilidade. ** PRODUTO HOMOLOGADO PELAS MONTADORAS ** Produto homologado pela BYD China. Especificações: - Marca: Ekap - Indicado para o veículo: Seal; - Versões aplicáveis: Todas as versões; - Material: borracha TPO flexível e resistente; - Formato: bandeja com bordas altas; - Resistência: à água, poeira, lama e produtos químicos leves; - Instalação: acoplamento no assoalho sem necessidade de ferramentas; Apresentação: 4 peças para: motorista, passageiro e banco traseiro Dimensões da embalagem: 90 x 60 x 15 cm Peso: 6 kg Garantia: 3 meses', 1299.9, 1234.91, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-81ztw-miulindapyboe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F58202521868', NULL, NULL, '2026-07-28T02:11:31.708458+