INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200498044', 'Jogo De Cama 200 Fios Vintage Kacyumara Cubes', 'A Linha 200 Fios Kacyumara foi desenvolvida para quem busca o equilíbrio ideal entre conforto, resistência e praticidade no dia a dia. Produzida em 100% algodão de fibra natural, oferece toque macio, frescor e excelente durabilidade, garantindo noites de sono confortáveis e revigorantes. Com acabamento superior e costuras reforçadas, os produtos dessa linha proporcionam ajuste perfeito e mantêm o tecido bonito por muito mais tempo. O entrelaçamento de 200 fios resulta em uma textura leve e agradável, ideal para o clima brasileiro e para quem prefere tecidos de toque natural e respiráveis. A Linha 200 Fios Kacyumara inclui jogos de cama, lençóis com elástico, fronhas e cobre-leitos coordenados, disponíveis nos tamanhos Solteiro, Casal, Queen e King, permitindo compor um enxoval harmonioso, elegante e completo. Composição: 100% Algodão 200 fios – toque macio e natural Destaques da linha: Toque suave e confortável Alta durabilidade e fácil manutenção Tecido respirável e antialérgico Ideal para uso diário Acabamento refinado e ajuste perfeito Disponível em diversas cores e estampas exclusivas Kacyumara Tamanhos: Solteiro, Casal, Queen e King A Linha 200 Fios Kacyumara é a escolha perfeita para quem valoriza qualidade, conforto e beleza em cada detalhe, com o padrão de excelência que faz da Kacyumara uma referência em roupas de cama.', 589.9, 471.92, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-821e3-mgwkc7zyoxzj3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F58200498044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097806409', 'Bermuda Infantil Menino Com Linho Hering Kids', 'Bermuda Infantil Menino Tradicional Com Linho. Toda elaborada em tecido de viscose com linho, aconchegante e sofisticado. Possui modelagem tradicional, com elástico aplicado no cós interno, cordel funcional para melhor vestibilidade e barras com dobras fixas. Apresenta bolsos funcionais embutidos na frente e nas costas com fechamento em botão. Ideal para aquele compromisso que exige um lookinho mais arrumadinho e sofisticado! Características da peça:Viscose com linhoModelagem tradicionalBolsosAbertura por botão e zíperElástico interno para ajusteO tecido kids que preferimos: O linho é um tecido que proporciona toque macio, caimento fluido e um visual sofisticado à peça. Além disso, traz conforto e leveza ao look, perfeito para os dias atuais.', 169.99, 169.99, NULL, 'Baby & Kids Fashion > Boy Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-lzqnfchi618723', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281598928%2F19097806409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
