INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53105497727', 'Mandioca Chips P&P Crocante, Natural e Sem Conservantes', 'A mandioca, raiz símbolo da nossa terra, transformada em um snack puro e crocante. Aqui, o protagonismo é do ingrediente — sem excessos, sem química, sem industrialização desnecessária. Benefícios: ✔ Apenas três ingredientes naturais ✔ Produzido com mandioca fresca ✔ Vegano, sem glúten e sem conservantes ✔ Ideal para lanches, aperitivos e acompanhamento Nós entregamos respeito. Respeito ao pequeno produtor, ao tempo da terra e ao seu corpo. Nossos chips são feitos com apenas 3 ingredientes: o legume fresco, óleo vegetal de alta qualidade e uma pitada de sal. Do campo direto para o seu momento de pausa. 🌱 Vegano | Sem Glúten | Sem Conservantes Peso: 500g - Pacote família *Imagem Ilustrativa', 49.97, 45.97, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk1ln7a4gq2o2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F53105497727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
