INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597088060', 'Fruteira Diva com Balcão para Microondas e Bebedouro Notável', 'Funcionalidade! Isso é o que a Fruteira Diva New da Notável Móveis oferece, pois em uma única móvel é possível manter tudo organizado com praticidade. Na sua prateleira interna, é possível guardar os alimentos ou eletrodomésticos de modo que fiquem protegidos. No tampo pode-se apoiar o forno micro-ondas com segurança. E ela possui ainda dois cestos em aramado que são mais resistentes e uma gaveta com corrediças metálicas para os objetos menores! Altura: 89 cm Comprimento: 103 cm Profundidade: 38 cm MDP 15mm Puxador ABS Dobradiça Metal Curva Corrediça Metálica 05 Pés fixos de plástico 2 cestos em aramado branco Pintura UV Brilho Suporte de peso cesto 2kg Suporte de peso total 40kg Garantia de 03 meses AVISO: Esclarecemos que a Opção Móveis se responsabilizará pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, ou seja: é de total responsabilidade do cliente a montagem, desmontagem e instalação do produto adquirido. Para evitar futuros desagrados ou imprevistos com a entrega, também é necessário que o cliente confira as dimensões do produto escolhido, antes de finalizar a compra, devendo certificar-se de que a mercadoria passará normalmente por elevador, porta, escada e corredor. Imagens ilustrativas. Objetos não acompanham o produto.', 413.64, 360.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lnefuf52s94y09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789777799%2F23597088060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193581093', 'Bucha para Drywall Gesso Pacote 25 unid 10mm Bg-01 Trifixi', 'A Bucha P/Gesso 10mm com Parafuso - Saco com 25 Peças Trifixi é a solução perfeita para fixações seguras em placas de gesso. Com um diâmetro de 10mm, este conjunto é ideal para pendurar diversos objetos como quadros, prateleiras e espelhos, garantindo estabilidade e segurança. A inclusão de parafusos de metal complementa o kit, proporcionando uma fixação eficiente que se integra perfeitamente ao estilo de qualquer ambiente. Esta bucha é fabricada em plástico resistente, assegurando durabilidade e resistência contra deformações durante o uso. Além disso, seu sistema de expansão ao inserir o parafuso aumenta a área de contato com a superfície, oferecendo uma instalação segura sem a necessidade de ferramentas especiais. Vantagens: Material plástico resistente que garante longa durabilidade. Diâmetro de 10mm, ideal para uso em placas de gesso. Saco com 25 unidades, permitindo múltiplas aplicações. Parafuso incluso em cada bucha, assegurando uma fixação estável. Design expansível, que aumenta a estabilidade quando o parafuso é inserido. Cor branca, que se mistura facilmente com as paredes de gesso. Especificações técnicas: Marca: Trifixi Material: Plástico resistente Diâmetro: 10mm Quantidade: Saco com 25 peças Cor: Branca Parafuso incluso: Sim Conteúdo da embalagem: 25 buchas de plástico resistente 25 parafusos Garantia: Garantia de 1 ano fornecida pelo fabricante', 43.9, 30.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3nzmtqrfjug14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23193581093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
