INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297672197', 'Kit 2 Protetor Solar Facial Isdin Fusion Water 5 Stars Color FPS 50 Cor Média 50ml', 'Protetor Solar Facial ISDIN Fusion Water 5 Stars Color FPS 50 Cor Média 50ml O Fotoprotetor ISDIN Fusion Water 5 Stars Color FPS 50 é um protetor solar facial com cor, textura ultraleve à base de água e de uso diário. A Fusion Water Color (cor média) tem FPS 50 e uniformiza o tom da pele, disfarça as imperfeições e proporciona cobertura natural. - Alta proteção UV FPS 50 avaliada clinicamente em laboratório e em condições reais de alta radiação solar. - Não irrita os olhos, testado oftalmologicamente. - Tolerância ótima com textura ultraleve de absorção imediata e controle da oleosidade da pele sem deixar resíduos. - Wet skin, pode ser aplicado na pele molhada. - Sea Friendly, fórmula com a maioria dos ingredientes biodegradáveis e/ou inorgânicos.', 209.98, 209.98, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-823on-mooibj5aj28d85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20297672197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
