INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17182713950', 'Kit com 12 Sabonetes Barra Hora do Sono Johnson''s Baby 80g', 'O Sabonete Barra Hora do Sono JOHNSON''S® Baby 80g foi desenvolvido com base em estudos científicos que desenvolveram uma rotina de cuidados que ajuda o seu bebê a dormir mais rápido e por muito mais tempo. Dermatologicamente testado e hipoalergênico, o sabonete oferece cuidado e proteção especialmente para a pele do seu bebê. - Rotina que comprovadamente ajuda seu bebê a dormir mais rápido e por mais horas durante a noite (estudos cientificos realizados no laboratório da J&J nos EUA. Resultados obtidos com base na rotina de banho e pós-banho do bebê); - Dermatologicamente testado; - Hipoalergênico (este produto foi formulado de maneira a minimizar possível surgimento de alergia).', 96.99, 96.99, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/b63ea834ed993fe04c6f9b9f7cdc0e74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F17182713950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
