INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51203522418', 'GUIDÃO PROTORK PRETO PARA HONDA CBX 250 TWISTER 2001 A 2008', 'O Guidão Protork Twister foi desenvolvido para garantir conforto, controle e segurança na pilotagem. Fabricado com material de alta resistência, oferece excelente durabilidade e acabamento de qualidade, sendo ideal tanto para reposição quanto para personalização da moto. Com design original e posição adequada, proporciona uma condução estável e ergonômica no uso diário ou em viagens. O acabamento na cor preta confere um visual esportivo e moderno à motocicleta. Características principais: Aplicação: Honda CBX 250 Twister 2001 a 2008 Marca: Protork Cor: Preto Modelo: Original Peso interno: Não possui Suporte/rosca para peso externo: Não possui Benefícios: Maior conforto e controle na pilotagem Alta resistência e durabilidade Encaixe perfeito sem necessidade de adaptações Excelente custo-benefício', 59.0, 59.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-81zvh-mim1yuvguj2860', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F51203522418', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
