INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41612488222', 'Creme Dental Colgate Total Original Mint Prevenção Ativa 90g', 'Colgate Total Original Mint, com prevenção ativa, é a escolha ideal para quem busca o melhor pasta de dente que combate a causa raiz dos problemas bucais***, antes que apareçam. O creme dental Colgate Total oferece 24 horas de proteção antibacteriana** e refrescância.Esta pasta de dente combate as bactérias que são a causa raiz de mau hálito, cáries, placa, tártaro e erosão do esmalte. O creme dental anticárie com flúor ajuda a limpar lugares difíceis de alcançar*. Seu uso regular ajuda a prevenir os problemas bucais mais comuns*** graças à sua fórmula com desempenho superior (em comparação a um creme dental normal com flúor sem ingrediente antibacteriano).A pasta Colgate Total tem prevenção de longa duração**, que ajuda a prevenir cáries e a fortalecer o esmalte. Para um cuidado ainda mais profundo, use Colgate Total Original Mint, prevenção ativa para uma limpeza profunda e proteção bucal completa.*vs apenas escovação.**Com escovação 2 vezes ao dia e uso contínuo durante 4 semanas.*** Ajuda a prevenir problemas bucais cosmeticos comuns causados por bacterias como: placa, cárie, tártaro e mau hálito.', 21.59, 21.59, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-mdc625atn8zkf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F41612488222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399380689', 'Tesoura corta vergalhão 14" c/ parafuso ajuste Vonder Plus', 'Conteúdo da embalagem 1 Tesoura corta vergalhão Aplicações e dicas de uso Indicada somente para cortar vergalhões com dureza máxima de 55 HRC e espessura máxima de 3/16" - 5 mm. Não utilizar para cortar cabos de aço, correntes ou cadeados. Destaques e diferenciais Possui parafuso de ajuste das lâminas, lâminas intercambiáveis fabricadas em aço cromo molibdênio e cabo com empunhadura plástica para maior conforto durante o manuseio DETALHES TÉCNICOS Material do cabo da tesoura corta vergalhão: Tubo de aço Material da lâmina da tesoura corta vergalhão: Aço cromo molibdênio Comprimento total da tesoura corta vergalhão: 14" - 350 mm Capacidade de corte da tesoura corta vergalhão: 3/16" - 5 mm', 97.9, 97.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-m04js2jscrwpf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F20399380689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
