INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21425834236', 'Odorizador de Ambiente Glade Frutas e Flores Vibrantes Automatic Refil 260ml Oferta Especial', 'Glade Automatic Spray te ajuda a deixar o ambiente mais aconchegante através de fragrâncias infundidas com óleos essenciais. O aparelho desenvolvido para complementar a decoração de qualquer ambiente é alimentado por pilha e libera automaticamente um spray discreto, de acordo com o ajuste de tempo de sua escolha. São até 60 dias de spray de fragrância, quando programado para liberação a cada 36 minutos. Não é necessário ligá-lo na tomada, basta programar e colocá-lo no cômodo desejado para aproveitar o conforto e perfume proporcionado.', 44.39, 44.39, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Air Fresheners & Home Fragrance', 'https://cf.shopee.com.br/file/sg-11134201-7rat6-matu7x22nfqu43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F21425834236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
