INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41952467724', 'Anel Masculino Retangular Liso Prata', 'Anel Masculino Retangular Liso Prata – Modernidade e Sofisticação O Anel Masculino Retangular Liso Prata é a escolha ideal para quem busca um acessório moderno, sofisticado e versátil. Com um design minimalista e acabamento polido, ele proporciona um visual elegante e atemporal, combinando perfeitamente com diferentes estilos, do casual ao clássico. Confeccionado em aço inoxidável de alta qualidade, esse anel oferece alta resistência e durabilidade, mantendo seu brilho impecável mesmo com o uso diário. Seu formato retangular exclusivo adiciona um toque de personalidade, tornando-se um complemento ideal para qualquer ocasião. Diferenciais do anel Design minimalista e sofisticado, ideal para qualquer estilo. Acabamento polido, garantindo um brilho duradouro. Disponível em 10 tamanhos, proporcionando um ajuste confortável e preciso. Medições Largura: 4 - 7 mm | Espessura: 2 mm. Realce sua personalidade com um acessório marcante O Anel Masculino Retangular Liso Prata é um item essencial para quem valoriza estilo e sofisticação. Adicione essa peça ao seu visual e tenha um acessório durável, elegante e versátil para todas as ocasiões. Após a confirmação da compra, a nota fiscal será enviada para o e-mail cadastrado em até um dia útil. Tamanho Diâmetro (mm) Circunferência (cm) 20 18,20 5,7 21 18,50 5,8 22 18,80 5,9 23 19,20 6,0 24 19,50 6,1 25 19,90 6,2 26 20,20 6,3 27 20,50 6,4 28 20,80 6,5 29 21,20 6,6', 279.8, 139.9, NULL, 'Fashion Accessories > Rings', 'https://cf.shopee.com.br/file/sg-11134201-7ratv-mabgtvnkkf4a5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411289902%2F41952467724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19457608851', 'Quarto de Bebê Completo com Berço Guarda-roupa e Cômoda Multimóveis 2869.010', 'O Quarto Infantil Meu Bebê Multimóveis é produzido em MDP, que garante maior durabilidade e resistência, e possui acabamento acetinado (cerca de 20% de brilho). O berço é padrão nacional (tamanho do colchão 1,30 x 0,60), possui grade fixa, 3 regulagens de altura para o colchão e acompanha suporte para mosquiteiro, que garante noites mais tranquilas de sono para o bebê. Compacta e versátil, esta linha conta módulos individuais e você pode montar da maneira que se adaptar melhor ao seu espaço. Berço certificado pelo INMETRO sob o Selo n° 001073/2017. Não acompanha colchão. Conteúdo da Embalagem: 1 (um) guarda-roupa 1 (uma) cômoda 1 (uma) prateleira 1 (um) berço Kit ferragem Manual de montagem Dimensões do produto montado: Altura: 137cm | Largura: 181cm | Profundidade: 133cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e a Multimóveis não disponibiliza o serviço de montagem.', 979.9, 899.99, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/sg-11134201-22100-gp57yp0034iv1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19457608851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
