INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697603409', 'Kit Cronograma Capilar Amend Pequeno', 'Kit Cronograma Capilar Amend Pequeno O kit contém: 01 Máscara Capilar Amend Hidratação 250g 01 Máscara Capilar Amend Nutrição 250g 01 Máscara Capilar Amend Reconstrução 250g O Cronograma Capilar Amend Máscaras essenciais é ideal para quem quer combater os danos e recuperar os fios, com mais maciez, movimento, controle e brilho. Indicado para cabelos danificados, ressecados, quebradiços e sem vida. - Máscara Amend Essenciais Hidratação: com leite de argan e pantenol ajuda a repor a umidade natural dos fios, para manter sempre hidratados, controlados, macios e com brilho. Além disso, fecha as cutículas, melhorando a flexibilidade do cabelo para mais sedosidade e vitalidade. - Máscara Amend Essenciais Nutrição: com manteiga de cereais, óleo de semente de girassol e mix de óleos nutri-funcionais, repõem os lipídios e ajudam a reter a umidade dos fios para manter a superfície do fio integra e homogênea enquanto nutre profundamente, evitando o ressecamento e promovendo mais suavidade, maciez e proteção contra pontas duplas. - Máscara Amend Essenciais Reconstrução: age profundamente na fibra, repondo os lipídios perdidos para força, resistência e flexibilidade dos fios. Além disso, equilibra a umidade do cabelo para mais condicionamento e maciez. Modo de usar: Após lavar com shampoo Amend, retire o excesso de água com uma toalha e aplique a máscara de acordo com o dia do seu cronograma*, do comprimento dos fios até as pontas, massageando mecha por mecha. Deixe agir por 03 minutos. Enxágue bem retirando todo o produto. Dica: se desejar, aplique a seguir o condicionador para selar as cutículas. *Alterne os produtos para obter um tratamento completo, de acordo com o cronograma capilar seguido.', 260.0, 260.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-lwsuwvha2nb0e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23697603409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293952329', 'Amplificador Guitarra Sheldon Gt1200 15 Watts Cubo Preto', 'Amplificador Sheldon GT1200 – Potência e Versatilidade para Guitarristas Iniciantes Descubra o Sheldon GT1200, o amplificador ideal para quem está começando no mundo da guitarra. Com 15W RMS de potência, oferece o volume perfeito para práticas em casa ou em pequenos ensaios. Equipado com o exclusivo efeito Turbo Drive, proporciona distorções encorpadas, permitindo explorar diversos estilos musicais. Seus controles de graves, agudos e volume master garantem total controle sobre o timbre, adaptando-se ao seu gosto pessoal. O design compacto e leve facilita o transporte, tornando-o o companheiro ideal para estudos em qualquer lugar. Disponível em várias cores vibrantes, como jeans, laranja, vermelho e preto, combina com o seu estilo. Principais características: Potência: 15W RMS Efeito: Turbo Drive (distorção) Controles: Graves, Agudos e Volume Master Saída para fones de ouvido: Sim Alto-falante: 6 polegadas Peso: 3,5 kg Dimensões: 265 x 143 x 256 mm Cor: Preto Por que escolher o Sheldon GT1200? Custo-benefício imbatível: Qualidade sonora a um preço acessível. Ideal para iniciantes: Simples de usar, perfeito para quem está começando. Praticidade: Leve, compacto e fácil de transportar. Estilo: Diversas opções de cores para combinar com sua personalidade. Invista no seu talento com o Sheldon GT1200 e dê os primeiros passos rumo ao sucesso musical', 539.9, 534.9, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-7rfht-m97bd8tnv99e51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780674849%2F23293952329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
