INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199648240', 'Kit Escovas Ortodônticas Bitufo Cônicas 3 a 6,2 milímetros', 'O Kit Ortodôntico de Bitufo garante higiene eficaz dos dentes e do aparelho ortodôntico, para uma escovação completa. A escova ortodôntica permite melhor higienização dos braquetes e dentes, a Intertufo promove a limpeza completa dos dentes e a interdental limpeza entre os dentes e braquetes, onde a escova não alcança. Disponível em rosa, roxo, azul e cinza. Atenção: esse produto possui as cores sortidas e a escolha é feita aleatoriamente no momento do envio do pedido. Disponível em rosa, roxo, azul e cinza.', 53.48, 53.48, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-m7742wjtmm4yc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F21199648240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
