INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40818429612', 'Kit Trava Abertura de Porta Malas Renault Kwid 2017 a 2024 Tragial', 'Kit Trava Abertura de Porta Malas Renault Kwid 2017 a 2024 Tragial Descrição do Produto: Kit de Trava de Abertura de Porta-Malas desenvolvido para aumentar a segurança e praticidade do seu veículo. Permite travar e destravar o porta-malas automaticamente via controle da chave ou alarme original, mantendo a originalidade do sistema. Modelo Disponível: RNMN012 Compatibilidade: Modelo: Kwid Anos: 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024 Especificações Técnicas: - Modelo Dedicado - Fácil Instalação Através dos Parafusos Originais - Tranca Fabricada em Aço Resistente - Revestimento em Plástico Reforçado - Tensão de Operação: 12V - Motor de 2 Fios - Ideal para o Porta Malas - Maior Segurança - Alta Durabilidade - Acompanha Botão Auxiliar - Compatível com Todos os Alarmes do Mercado (Não Acompanha Alarme) - Sistema de Travamento Via Alarme ou Interruptor Vantagens de Uso: - Maior segurança contra furtos do porta-malas - Abertura e fechamento automáticos pelo controle do carro - Instalação simples e compatível com sistemas originais - Preserva a estética e originalidade do veículo Conteúdo da Embalagem: - 01 Trava Elétrica - 01 Botão Auxiliar - Chicote Elétrico - Manual de Instalação Importante: - 02 anos de garantia pelo fabricante; - Imagens meramente ilustrativas fornecidas pelo fabricante; - A E-Automotivo recomenda que para garantir o funcionamento correto e evitar danos ao sistema elétrico do veículo, recomenda-se que a instalação seja feita por um profissional qualificado. - Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo. –', 176.0, 167.2, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Locks', 'https://cf.shopee.com.br/file/sg-11134201-824gr-meho1osnywhwc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F718208305%2F40818429612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
