INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594187488', 'Resina Auto Brilho Pintura Carro Efeito Teflon 500ml', 'Box 21 Resina veio para revolucionar o tratamento de estética que você tem com o seu carro. O Produto cria uma camada super LISA na pintura do seu veículo protegendo e dando efeito de carro de concessionaria. Basta aplicar com um borrifador e com duas flanelas uma espalhando e a outra lustrando. ATENÇÃO! Para carros com a pintura muito queimada e antiga o produto não substitui uma pintura nova ou um polimento com maquina e pasta de polimento. Resina intensificadora de brilho de pintura automotiva Líquida Profissional O kit contém: 1 Unidade de 500ml cada da Resina Líquida Profissional Box 21 Resina Para mais unidades consulte valores em ATACADO! Aplicação: Após a lavagem, pulverizar a Resina Líquida Profissional Box 21 Resina intensificadora de brilho sobre o veículo e espalhe com o auxilio de uma toalha de microfibra e em seguida dê o brilho usando outra toalha de microfibra. Efeito do Produto: Auto brilho instantâneo e proteção a pintura, criando uma película de Teflon sobre o verniz. Rendimento: Cada unidade de 500ml rende mais de 10 aplicações.', 12.9, 12.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/sg-11134201-7ra18-mbgyvd03ansl3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F735686176%2F22594187488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
