INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099476473', 'Shorts Infantil Menina Lilica Ripilica', 'Shorts infantil desenvolvido para a fase Mini, uma linha pensada especialmente para o universo das crianças, com peças mais lúdicas, confortáveis e cheias de delicadeza. Confeccionado em tecido skin, o modelo oferece toque macio, leveza e conforto para o dia a dia. Possui elástico no cós fora a fora, garantindo ajuste prático e confortável ao vestir. Todo estampado, o shorts ganha ainda mais charme com a estampada localizada da Lilica Ripilica, aplicada de forma delicada e encantadora. Uma peça versátil e confortável, ideal para acompanhar as crianças em momentos de brincadeira, passeios e produções leves e cheias de estilo.', 149.0, 149.0, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-820lj-mnn0difxa8so82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F22099476473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997085152', 'Amigos, Amores e Aquela Coisa Terrível', 'O amado astro de Friends nos conduz aos bastidores dessa série de sucesso e narra a luta que enfrentou contra o vício neste sincero livro de memórias. Divertido e revelador, Amigos, Amores e Aquela Coisa Terrível&#160 traz uma poderosa mensagem de esperança e resiliência. Prefácio de Lisa Kudrow. &#160 “Oi, meu nome é Matthew, embora talvez você me conheça por outro nome. Meus amigos me chamam de Matty. E eu devia estar morto.” Assim começa a fascinante narrativa do aclamado ator Matthew Perry, que nos guia pelas intensas e sensíveis memórias de sua trajetória, desde a ambição de infância em alcançar a fama à luta contra o vício e à sua recuperação após um susto ocasionado por um problema de saúde que pôs em risco sua vida. Antes das frequentes visitas ao hospital e passagens por centros de reabilitação, havia o pequeno Matthew de 5 anos, que viajou de Montreal a Los Angeles, se dividindo entre pais divorciados o adolescente de 14 anos, uma estrela do tênis canadense em nível nacional o jovem de 24 anos, que conquistou o cobiçado papel como um dos protagonistas do piloto da tão comentada e até então intitulada série Friends Like Us… e muito mais. Em uma narrativa impactante — relatada de uma maneira sincera, hilariante e calorosa que apenas ele seria capaz de fazer —, Matthew Perry conta sobre a família fragmentada que o criou (e que também o deixou por conta própria), o desejo por reconhecimento que o conduziu à fama e a constante sensação de vazio, que não seria preenchido nem mesmo ao ver seus maiores sonhos se tornarem realidade. Matthew apresenta também detalhes sobre a paz encontrada na sobriedade e como se sente a respeito da onipresença da série Friends, compartilhando histórias sobre colegas de elenco e outras celebridades que conheceu pelo caminho. Franco, autoconsciente e munido do seu humor característico, Perry retrata com vivacidade a batalha travada ao longa da vida contra o vício e o que o levava a essa escolha, apesar de ter conquistado tantas coisas — tudo com que aparentemente alguém poderia sonhar. Amigos, Amores e Aquela Coisa Terrívelé um livro de memórias inesquecível, ao mesmo tempo íntimo e elucidador — além de um conforto para aqueles que estão lutando para manter a sobriedade. Dolorosamente sincero, comovente e, ainda assim, incrivelmente engraçado, este é o livro pelo qual os fãs estavam esperando.', 64.78, 64.78, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/sg-11134201-7rblv-ln9ddu78ekhh3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23997085152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392592201', 'O livro secreto do escritor', '“Quando estava começando minha carreira há nove anos, Lilian me ajudou colocando meus livros em destaque na mídia, depois me ajudou com a publicação independente do meu primeiro New Adult.[...]” — Babi A. Sette, escritora best-seller, reconhecida por publicar obras young adult e pioneira em romances de época no Brasil Após ouvir por anos a frase “Eu adoraria escrever um livro, mas não sei por onde começar”, a especialista em marketing Lilian Cardoso decidiu reunir toda sua experiência no mercado editorial para democratizar o ensino sobre como escrever, publicar e divulgar obras de qualidade. O resultado desta imersão é O Livro Secreto do Escritor. Nele, a escritora revela os bastidores do mundo literário, detalha as etapas de lançamentos e desmistifica os rankings dos mais vendidos que, muitas vezes, parecem enigmáticos. O coração deste título, no entanto, está na segunda parte: Um workbook para escritores que vai guiá-lo da escolha do tema à conexão com os leitores. Cada capítulo apresenta técnicas, exercícios e ferramentas que ajudarão você a transformar ideias em obras admiradas. Durante a leitura, você vai: Descobrir qual é e como atrair o público-alvo Escolher os melhores caminhos de publicação e negociar contratos editoriais de forma confiante Trabalhar o marketing — a etapa que vai fazer o seu projeto se destacar entre tantas outras publicações. Seja você um escritor iniciante ou experiente em busca de novas estratégias para conquistar o mercado, saiba que este guia tem no título a palavra “secreto” não somente pelo que é revelado, mas porque vai trazer à tona as suas ideias mais originais. Aproveite também os QR Codes com informações atualizadas para ampliar o seu conhecimento neste apaixonante mundo literário.', 56.09, 56.09, NULL, 'Books & Magazines > Books > Business & Investment', 'https://cf.shopee.com.br/file/sg-11134201-7r992-ln7quz4bf7s1b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22392592201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
