INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40662667861', 'Suiiki: Território das Águas (Volume Único)', 'UM TRABALHO FANTÁSTICO DA MESMA AUTORA DO SUCESSO MUSHISHI. Uma cidade com racionamento de água devido ao contínuo calor intenso. Uma vila na montanha com uma chuva que nunca para. A estudante Chinami acorda em um segundo mundo. Aquilo que a conecta é uma memória no subconsciente da sua família…', 74.83, 74.83, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdwe-mddrk8aq9j5obe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F40662667861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
