INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798833119', 'Desodorante Red Apple Creme Limão 55g', 'Características do Produto: Marca: Red Apple Contéudo: 55g Linha do Produto: Limão e Chá Verde Características Adicionais: Combate o suor e os odores, garantindo uma sensação de frescor prolongada. 48h de Proteção Seca. 0% de álcool e 0% de corantes, ideal para todos os tipos de pele, até as mais sensíveis. Dermatologicamente Testado. Produto vegano. Indicações, modo de usar e aplicações: Aplique somente nas axilas. Espere secar para se vestir. Suspenda o uso em caso de irritação. Não aplique próximo a mucosas, pele lesionada ou irritada. Mantenha fora do alcance das crianças. Não usar em crianças. Caso ocorra irritação e/ou prurido no local da aplicação, suspender o uso imediatamente. Não contém álcool etílico. Fornecedor: CPM3 - Distrib de Comésticos Ltda', 18.18, 18.18, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-824ir-mpiayg4t807g0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22798833119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899890879', 'Kit 2 Pneus Hifly Vigorous AT601 265/65R17 112 T Caminhonete Carro Suv Bicos Brinde Envio Imediato', 'Kit 2 Pneus HIFLY 265/65R17 112T VIGOROUS AT601 – Desempenho, Durabilidade e Segurança em Qualquer Terreno O pneu Hifly Vigorous AT601 265/65R17 112T é a escolha ideal para quem busca equilíbrio entre conforto, tração e resistência em todos os tipos de vias. Projetado para SUVs e picapes, oferece excelente desempenho tanto no asfalto quanto em terrenos off-road leves. Principais Benefícios: ✅ Desempenho All Terrain (AT) Desenho simétrico que garante aderência e estabilidade em pisos secos, molhados e não pavimentados. ✅ Alta Durabilidade Treadwear 460 — excelente rendimento quilométrico e desgaste uniforme, ideal para uso misto. ✅ Conforto e Baixo Ruído Tecnologia de construção radial com desenho otimizado, garantindo rodagem silenciosa e confortável. ✅ Segurança e Aderência Classificação “A” em tração e “B” em temperatura, garantindo frenagens seguras e estabilidade mesmo em altas velocidades. ✅ Economia e Custo-Benefício Pneu resistente, eficiente e com excelente relação entre preço e performance. Características Técnicas: Marca: Hifly Modelo: Vigorous AT601 Medida: 265/65R17 Índice de carga: 112 (até 1120 kg por pneu) Índice de velocidade: T (até 190 km/h) Treadwear: 460 Traction: A Temperature: B Eficiência: E Aderência: C Ruído: 72 dB Construção: Radial Tipo: Sem câmara (Tubeless) Desenho: Simétrico Lateral: Letras Pretas Aplicação: ✅ Indicado para SUVs, caminhonetes e utilitários de uso misto (asfalto e terra). Compatível com modelos como: Toyota Hilux Chevrolet S10 Ford Ranger Nissan Frontier Mitsubishi L200 E outros veículos que utilizam pneus 265/65R17. Sobre a CERIOLLI SHOP: ✅ Mais de 16 anos de experiência no mercado automotivo ✅ Envio rápido e seguro com embalagem reforçada ✅ Atendimento técnico personalizado ✅ Compra com nota fiscal e garantia total', 2240.25, 2240.25, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfjsufj8llhh30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F21899890879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096016323', 'Bola de Basquete Tamanho 7 Oficial Indoor Outdoor Vollo', 'Bola de Basquete Tamanho 7 Oficial Vollo A Bola de Basquete Tamanho 7 Oficial Indoor Outdoor Vollo foi desenvolvida exclusivamente para atletas que buscam a cesta de 3 pontos! Perfeita para jogos de quadra indoor ou outdoor, ou seja, você pode jogar nas ruas ou quadras e a qualidade se mantém a mesma. Demais né? E tem mais, a bola de basquetebol da Vollo possui tamanho oficial para as competições masculinas, além de texturas na superfície que garantem maior aderência, controle e precisão no momento do passe ou arremessos. Marque a sua cesta com estilo com a Bola de Basquete Vollo! Principais Benefícios da Bola de Basquete Vollo • Maior firmeza e aderência no toque • Equilíbrio e precisão nos arremessos • Tamanho oficial: competição masculina • Equilíbrio e precisão durante os movimentos • Composição: Borracha • Diâmetro: 25cm • Peso aproximado: 614g', 119.9, 94.63, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Basketball', 'https://cf.shopee.com.br/file/sg-11134201-7rd4g-m6rfv1vbbv8yd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1001649409%2F23096016323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894837399', 'L''Oréal Professionnel Vitamino Color Spectrum - Shampoo 300ml', 'O Shampoo L''Oréal Professionnel Vitamino Color Spectrum foi desenvolvido pelos especialistas da L''Oréal Professionnel para cuidar especialmente dos cabelos coloridos, garantindo resultados extraordinários de proteção e manutenção da cor. Sua fórmula revolucionária combina Ácido Ferúlico e Ácido Cítrico em uma concentração de 2,5%, criando uma eficiente tecnologia que fixa os pigmentos na fibra capilar, preservando a cor vibrante por até 100 dias de uso contínuo. Este shampoo atua em cinco dimensões essenciais da cor: Proporciona brilho espelhado ultraintenso, mantém a saturação com cores ricas e vibrantes, preserva o contraste ideal entre diferentes tons, neutraliza reflexos indesejados e conserva os níveis de luminosidade e profundidade. Sua textura cremosa produz uma espuma densa e luxuosa que limpa completamente o cabelo, deixando-o instantaneamente nutrido, mais forte e protegido. A fórmula ultra hidratante envolve cada fio em um tratamento completo, devolvendo maciez, sedosidade e vitalidade aos cabelos coloridos que precisam de cuidados específicos para manter a beleza duradoura da coloração. Como usar: Aplique uniformemente nos cabelos úmidos. Massageie até obter uma espuma rica. Enxágue bem. Prossiga com o Vitamino Color Spectrum condicionador profundo ou a máscara e o Glass Shine Serum. *Teste instrumental com a linha completa Vitamino Color Spectrum **Teste instrumental com a linha completa Vitamino Color Spectrum após 4 semanas. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 185.9, 185.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mk14hlq7d69z52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22894837399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098437732', 'Pastilha de Freio Traseiro Bmw R 1200 2014 a 2019 COBREQ', 'Descrição: A Pastilha de Freio COBREQ N-1806 é uma peça que serve na posição Traseiro dos veículos BMW K 1200, K 1300, R 1100, R 1150, R 1200. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Altura: 101 mm - Comprimento: 942 mm - Largura: 364 mm - Posição: TRASEIRO - Tipo de pastilha de freio: LINHA RACING - ORGÂNOMETÁLICO HP Aplicação: - BMW K 1200 R 1.2 L 16V DOHC L4 2005 a 2008; - BMW K 1200 S 1.2 L 16V DOHC L4 2005 a 2008; - BMW K 1300 R 1.3 L 16V DOHC L4 2009 a 2014; - BMW K 1300 S 1.3 L 16V DOHC L4 2009 a 2008; - BMW R 1100 S 1.1 L 8V DOHC BOXER2 2001 a 2002; - BMW R 1150 GS 1.1 L 8V DOHC BOXER2 2002 a 2003; - BMW R 1150 GS ADVENTURE 1.1 L 8V DOHC BOXER2 2002 a 2005; - BMW R 1150 R 1.1 L 8V DOHC BOXER2 2001 a 2006; - BMW R 1150 R ROCKSTER 1.1 L 8V DOHC BOXER2 2003 a 2006; - BMW R 1200 GS 1.2 L 8V DOHC BOXER2 2014 a 2019; Sobre o Peça Aí: Com o Peça Aí, você acha a peça certa para cada carro e compra num só lugar. É o maior estoque digital de peças do país! São mais de 100 mil itens originais e de reposição à sua disposição. Importante: • Dúvidas: Caso tenha qualquer dúvida sobre as aplicações do produto, entre em contato conosco. • Instalação Profissional: Recomendamos que a instalação do produto seja realizada por profissionais especializados. • Responsabilidade: Não nos responsabilizamos por montagens mal realizadas e equívocos de instalação." • Produto novo, original e com nota fiscal.', 101.73, 101.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7renp-m8xid3ei1sknb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fp