INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694847976', 'L''Oréal Paris Dermo Expertise Base Média - BB Cream 30ml', 'BB cream para todos os tipos de pele.BB Cream L''Oréal Paris disfarça as imperfeições, protege e uniformiza o tom. O BB CreamL''Oréal possui proteção UV e ação antibrilho, para uma performance que dura o dia inteiro. Possui ainda textura agradável, de rápida absorção, e leve toque de cor com radiante. Um produto multifuncional 5 em 1: Hidrata a pele, suaviza imperfeições, uniformiza e ilumina, possui ação antibrilho e proteção contra os raios UV, FPS 20. Um toque seco confortável, com inúmeros benefícios! BB CreamL''Oréal cores disponíveis: Clara, Média e Escura. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 61.9, 61.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8261a-mlnse0210veq0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22694847976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
