INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698028341', 'Suporte Para Banheira Universal Rosa', 'Suporte Para Banheira Universal Rosa O Suporte para Banheira Universal Rosa é a solução perfeita para transformar a hora do banho do seu bebê em um momento ainda mais prático e confortável. Com design elegante e funcional, este suporte é ideal para mães e pais que buscam facilidade e segurança, garantindo a posição ideal da banheira na altura certa, evitando dores nas costas durante o banho. Feito com materiais resistentes e de alta qualidade, o suporte possui uma estrutura robusta, mas leve, garantindo estabilidade e segurança durante o uso. Seu tom rosa suave confere um toque delicado e encantador ao ambiente, adicionando charme ao espaço do bebê com um design moderno e atemporal. A compatibilidade universal permite que o suporte seja utilizado com diferentes modelos de banheiras, oferecendo versatilidade e comodidade. Além disso, sua montagem e desmontagem são rápidas e simples, facilitando o armazenamento quando não estiver em uso. O suporte conta com pés antiderrapantes, garantindo mais firmeza e estabilidade enquanto o bebê é banhado. Com o Suporte para Banheira Universal Rosa, o momento do banho se torna muito mais prático, seguro e confortável, proporcionando ao seu bebê uma experiência relaxante e aos pais uma solução eficiente e funcional. O suporte para banheira Ninos é produzido em tubo de aço, arame trefilado em pintura epóxi, com abas de segurança e pés antiderrapantes.Resistentes e estáveis, as banheiras são essenciais para a hora do banho, quanto mais confortável o bebê está na banheira, maior é a garantia da higiene e relaxamento. Informações Adicionais: Tamanho: Único Referência: 0003 Medidas Aproximadas: 70cm x 62cm x 44cm Marca: Ninos', 117.9, 117.9, NULL, 'Mom & Baby > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbkd-m5ye06wkevbra3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F19698028341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299182277', 'Kit 6 Mijões Culotes com Cós Largo Confortável Bebê RN ao G', 'Kit 6 Mijões Culotes com Cós Largo Confortável para Bebê RN ao G – Suave e Não Aperta o Umbiguinho O Kit com 6 Mijões/Culotes com Cós Largo é perfeito para garantir o conforto do seu bebê nos primeiros meses! Feito com tecido macio e respirável, esse modelo possui cós largo, que se ajusta suavemente ao corpinho sem apertar a barriguinha nem o umbigo — ideal para recém-nascidos e bebês em crescimento. ? Diferenciais: Cós largo e maleável: mais conforto e segurança para o bebê Não aperta o umbiguinho Tecido leve, macio e de fácil lavagem Ideal para uso diário Excelente custo-benefício ?? Contém: 6 mijões/culotes infantis ?? Tamanhos disponíveis: RN | P | M | G Indicado para: meninas de 0 a 12 meses Características: Kit com 6 mijões canelados Com pés reversíveis, práticos e confortáveis Tecido macio e agradável ao toque Modelagem que proporciona liberdade de movimentos Ideal para o dia a dia ou para combinar com outros tops e bodies Informações Adicionais: Tamanho: RN ao G Cores: Colorido Referência:519 Marca: Top Chot', 106.9, 106.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-821er-mgnztsk2w7ij31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22299182277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
