INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197972094', 'Kit Pano De Boca Bordados Papi Prendedor Ted Balão - 3 Peças', 'Kit Pano De Boca Bordados Papi Prendedor Ted Balão - 3 Peças O Kit Pano de Boca Bordados Papi é um conjunto encantador e funcional, ideal para os cuidados diários com o seu bebê. Composto por 3 unidades, cada pano de boca é confeccionado em tecido 100% algodão, garantindo suavidade ao toque e conforto para a pele sensível do bebê. O viés de malha conta com um prático prendedor de chupeta, proporcionando praticidade e evitando que a chupeta se perca. O detalhe de faixa estampada e o bordado personalizado adicionam um toque charmoso e personalizado a cada peça. Além de sua função tradicional para higiene, os panos de boca podem ser utilizados como itens decorativos no enxoval do bebê. O prendedor de chupeta integrado é uma solução conveniente para manter a chupeta sempre à mão durante os passeios. Informações Adicionais:Tamanho: Único Cor: Bege Referência: 4928-4005 Medidas aproximadas: 40cm x 40cm Marca: Bordados Papi', 36.8, 36.8, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdwi-m1ik35ig63wof7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23197972094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
