INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694033318', 'Algodão Quadrado Lunis Pequeninos c/ 50 Un – Não Solta Fiapos', '**Produto Original** Algodão Quadrado Lunis Pequeninos c/ 50 Un – Não Solta Fiapos Características principais: Embalagem com 50 unidades de algodão quadrado Duas faces com textura macia e resistente Tamanho ideal para manuseio com mais facilidade Não solta fiapos: ideal para remoção de maquiagem Tecnologia exclusiva que evita desfiar durante o uso Indicado para limpeza facial e cuidados com a pele Descrição detalhada: O Algodão Lunis Pequeninos com 50 Quadrados é ideal para quem busca precisão, suavidade e praticidade nos cuidados com a pele. Com formato quadrado e tamanho perfeito para as mãos, facilita a remoção de maquiagem, aplicação de loções ou limpeza facial com mais controle e conforto. Possui duas faces desenvolvidas com tecnologia exclusiva, que proporcionam maior resistência e não soltam fiapos, mesmo durante o uso repetido ou com produtos líquidos. É a escolha ideal para uma rotina de beleza mais eficiente e higiênica. Indicações de uso: Limpeza facial diária Aplicação e remoção de maquiagem Uso com tônicos, demaquilantes e loções Cuidados estéticos em geral Especificações: Marca: Lunis Tipo: Algodão em quadrados Quantidade: 50 unidades Formato: Quadrado Composição: 100% algodão Uso: Adulto, estético e dermatológico Adicione oAlgodão Lunis Pequeninos Quadrado à sua rotina de cuidados com a pele e descubra o conforto de um produto que não solta fiapos e respeita sua beleza!', 20.99, 20.99, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rdxd-mbqzqviqui52a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22694033318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898790530', 'Kit Extratora Vonder Com Produto de Limpeza Sanitizante Extractus Bactran', 'Kit Extratora Portátil para Limpeza + 2 Limpadores Profissionais – VONDER ELV 400 + Extractus + Bactran Vonixx Limpeza insana de estofados? Esse kit resolve! O combo perfeito para quem trabalha com higienização profissional ou quer elevar o nível da limpeza doméstica. A extratora Vonder ELV 400 é portátil, potente e fácil de usar, ideal para sofá, colchão, carpetes, bancos de carro e muito mais. Acompanha dois limpadores concentrados top de linha: Extractus para sujeiras pesadas e Bactran para desinfecção completa com ação antimanchas e antifúngica. - Itens Inclusos: • 1 Extratora Vonder ELV 400 – 400W • 1 Bocal simples • 1 Bocal 3 em 1 (pulveriza, esfrega e extrai) • 1 Extractus Vonixx 1,5L – limpeza pesada de estofados • 1 Bactran Vonixx 1,5L – bactericida, tira manchas, desinfetante • 1 Sanitizante - Especificações Técnicas da Extratora: • Potência: 400 W • Tensão: 220 V ~ • Capacidade reservatório água limpa: 1,3 L • Capacidade reservatório água suja: 500 ml • Função 3 em 1 no bocal: pulveriza, esfrega e extrai • Dupla isolação para mais segurança • Produto certificado Inmetro conforme Portaria nº 148/2022 Por que escolher este kit? Produto novo e original Vonder + Vonixx Limpeza profunda, profissional e eficaz Remove manchas, sujeiras pesadas e ainda desinfeta Pronta entrega com envio em até 24 horas Compra 100% segura', 704.9, 704.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7rdxm-md25xiby1owe49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F22898790530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
