INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493886759', 'Alfaparf Milano Semi Di Lino Moisture Condicionador', 'Alfaparf Semi Di Lino Moisture Nutritive Condicionador sem enxágue para cabelos ressecados ou secos. Alfaparf Semi Di Lino Moisture Nutritive Leave-in Conditioner nutre e traz toque suave para os fios. Perfeito para quem deseja mais brilho e vida para o cabelo. O Condicionador Leave-in Semi Di Lino Moisture, de Alfaparf, carrega em sua composição açúcares nutritivos que hidratam profundamente a fibra capilar para devolver toda a sua maciez, movimento e saúde. Além disso, assim como toda a linha Semi Di Lino, ainda conta com as tecnologias de proteção contra a poluição urbana, ação antioxidante e proteção UV para preservar a coloração dos fios, e proporciona brilho intenso por até 24 horas.', 129.99, 129.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7reob-m8dc4j3qkhbd81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F23493886759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54958956925', 'Frescobol De Madeira Aloha 3699 Mor', 'O Frescobol de Madeira Aloha 3699 Mor é a escolha ideal para quem busca diversão ao ar livre com qualidade e estilo. Produzido em madeira resistente, o conjunto oferece durabilidade e excelente desempenho durante as partidas, seja na praia, no parque ou no quintal. Seu design leve e anatômico garante conforto no manuseio, facilitando o controle dos movimentos e proporcionando jogadas mais precisas. As raquetes contam com acabamento suave e estampa tropical vibrante, que remete ao clima descontraído do verão. Acompanha bola leve, ideal para trocas rápidas e dinâmicas entre os jogadores, tornando a experiência ainda mais envolvente. Perfeito para todas as idades, o frescobol estimula a coordenação motora, a prática de atividades físicas e momentos de lazer em grupo. Fácil de transportar, é uma ótima opção para levar em viagens e aproveitar qualquer momento com energia, descontração e muita diversão.', 40.99, 39.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Tennis', 'https://cf.shopee.com.br/file/sg-11134201-81zv9-mn4fgsnta9l4bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F54958956925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
