INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28989521254', '(Férias) Lovito Blusa com Babado para Primavera/verão para mulheres L143ED491', '✅DESTAQUES -❤️Babado -❤️Padrão -❤️Curva -se para trás -❤️Boa textura -❤️Primavera e verão ✅DESCRIÇÕES Estampa / Padrão:Floral Estilo:Casual Tamanho Plus:Não Material:Poliéster Composição:95% Poliéster + 5% Elastano Tipo de modelagem:Regular Fit Transparência:Não Esticar:Não esticado Feito na China ✅O PACOTE INCLUI 1XBlusa ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 59.9, 41.9, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-7rdxm-mde627gzqf9387', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F28989521254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998058993', 'Par de Palhetas para Ford Ka 2008 até 2013 Gancho Limpador do Para brisa Automotiva Silicone Cinoy', 'ATENÇÃO! Alguns modelos do Ford Ka, mesmo sendo do ano e modelo citado, podem possuir palhetas de tamanhos diferentes ou encaixe diferentes. Por isso, recomendamos medir antes da compra e confirmar se a palheta possui 41 cm para lado direito e 49cm para lado esquerdo. Caso a medida seja diferente, nos chame no chat para indicarmos o modelo menor compatível com o seu veículo. Especificações Técnicas • Desenho aerodinâmico para evitar ruído sonoro • Fabricado em Silicone • Rápida Instalação • Fácil de Encaixar • Não enferruja • Pressão uniforme em todo parabrisa • Lado esquerdo: 19 polegadas (49cm) • Lado direito: 16 polegadas (41cm) Compatibilidade • Ford Ka 2008 - 2013 Conteúdo da Embalagem • 02 Palhetas Cinoy Ford Ka', 23.99, 23.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-8260d-mlz7rl931szs0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1273324128%2F23998058993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
