INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199633511', 'Bomba De Ar Kagiva Encher Calibrar Bola Bombinha Futsal Vôlei Futebol Basquete Dupla Ação + Agulha', 'CARACTERÍSTICAS: • Modelo: Bomba Inflar Way • Marca: Kagiva • Material da Bomba: Plástico Rígido (ABS) • Material do Bico: Metal (Zinco e Cobre) • Material do Prolongador: Borracha • Dimensões: 23 cm (comprimento) x 2 cm (altura) x 12 cm (largura) • Peso: 60 g A Bomba de Ar Kagiva Dupla Ação é a escolha ideal para atletas e entusiastas de esportes que buscam eficiência e praticidade. Com seu sistema de dupla ação, ela infla as bolas tanto no movimento de empurrar quanto no de puxar, garantindo rapidez e menos esforço durante o uso. Fabricada com materiais de alta qualidade, como plástico rígido e bico metálico, esta bomba oferece durabilidade e resistência. Seu design compacto e leve facilita o transporte, sendo perfeita para levar em treinos, jogos ou atividades ao ar livre. BENEFÍCIOS: • Inflação Rápida e Eficiente: O sistema de dupla ação permite inflar as bolas em menos tempo, otimizando sua preparação para o jogo. • Compatibilidade Universal: Adequada para diversos tipos de bolas esportivas, como futebol, basquete, vôlei e handebol. • Portabilidade e Conveniência: Leve e compacta, pode ser facilmente transportada na mochila ou bolsa esportiva. DIFERENCIAIS TÉCNICOS: • Sistema Dupla Ação: Infla nos dois sentidos do movimento, proporcionando eficiência e economia de tempo. O QUE ESTÁ INCLUSO? 1 Bomba de Ar Kagiva Dupla Ação 1 Agulha Metálica O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes.', 71.12, 34.9, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9j088cb2osia2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F18199633511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398674749', 'Par de hastes com dobradiças para Notebook Aspire A315-41', 'Par de hastes com dobradiças para Notebook Acer Aspire A315-41 Estas hastes com dobradiças para notebook são a solução para seus problemas com o movimento de abrir e fechar a tampa do seu computador. O produto é novo, feito em material resistente e a embalagem contém duas unidades para montagem e fixação nos lados direito e esquerdo da carcaça do notebook. Com as hastes e dobradiças novas você soluciona alguns problemas: - Dificuldade ao abrir e/ou fechar o notebook - Tampa do notebook está frouxa e/ou mole - Barulho ao abrir e/ou fechar a tampa - Elevação ou rachadura na carcaça do notebook Atenção! É importante verificar a compatibilidade das hastes e dobradiças com o seu modelo de notebook para que sejam exatamente as peças que seu computador precisa. Garantia: 3 meses de garantia contra defeitos de fabricação Referência: HT057-AC-0002', 49.87, 44.88, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mq6riqrzdhc003', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23398674749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
