INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999604634', 'Disney Frozen Castelo da Elsa Empilhável - Mattel', 'Disney Frozen Castelo da Elsa Empilhável - MattelO Disney Frozen Castelo da Elsa Empilhável é uma incrível casa de bonecas em miniatura inspirada nos filmes da Disney. Este conjunto encantador se abre para revelar diversas áreas de lazer, incluindo uma boneca da Elsa, uma figura do Olaf, móveis e muitos acessórios. Com uma alça para transporte, você pode levar essa diversão onde quer que vá. Diferenciais:Conjunto completo com boneca, figura do Olaf e móveis. Design encantador inspirado em Frozen da Disney. Possui alça para transporte e é empilhável. Ideal para fãs de Frozen explorarem o mundo mágico de Elsa. Mais sobre o Produto:O Castelo da Elsa se fecha compacto e se abre para revelar um espaço de diversão com 1 mini princesa de 9cm, 8 acessórios e o adorável Olaf. Seu design empilhável facilita o transporte e armazenamento, enquanto a alça proporciona praticidade para levar a brincadeira para onde quiser. Dicas de Uso:Perfeito para crianças explorarem a imaginação e recriarem suas cenas favoritas de Frozen. O Castelo da Elsa é ideal para brincadeiras individuais ou compartilhadas com amigos. Combine-o com outros produtos da linha para expandir o universo de Frozen. Ficha Técnica:Marca: Mattel; Nome do produto: Disney Frozen Castelo da Elsa Empilhável; Idade recomendada: A partir de 3 anos; Selo Inmetro: 005388/2021; Contém: 1 conjunto empilhável, 1 boneca, 3 amigos personagens e 6 acessórios.', 295.99, 295.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rce7-m6mmudpq1vh6b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19999604634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
