INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499360913', 'Suporte Celular Para-brisa Super Fixador Para Painel Carro', 'O Suporte Celular Veicular 360 Poderoso Fixador é a solução perfeita para manter seu celular seguro e acessível enquanto você dirige. Dimensões da base: 7.3cm (esse é o espaço que deverá ter no painel do seu veículos livre para a instalação desse suporte). Compatível com todos os modelos de celulares até 6.6 polegadas, este suporte oferece uma fixação firme e confiável nas garras retráteis do suporte. Sua montagem é fácil e rápida, podendo ser encaixado no painel ou parabrisa veicular, vidro, granito ou azulejo. Com um design elegante na cor preta, este suporte se adapta perfeitamente ao interior do seu veículo. Além disso, seu tamanho permite que você o leve para qualquer lugar. Não perca tempo e adquira agora o Melhor Suporte Celular Veicular para uma experiência de condução mais segura e conveniente. Garantia do vendedor: 30 dias', 33.0, 25.97, NULL, 'Mobile & Gadgets > Accessories > Phone Grips', 'https://cf.shopee.com.br/file/sg-11134201-82623-mlt4ygg1hq84fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F21499360913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
