INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252189661', 'Limpol Neutro Detergente Líquido', 'O Detergente Líquido Neutro Limpol é ideal para a remoção eficiente de gorduras de louças, talheres e panelas, deixando suas mãos macias graças à sua fórmula com glicerina. * Dermatologicamente testado * Ação antiodor e desengordurante * Contém conservantes * Embalagem squeeze de 500ml', 3.49, 3.49, NULL, 'Home Appliances > Kitchen Appliances > Dishwashers', 'https://cf.shopee.com.br/file/sg-11134201-825ba-mqnekzj3ulmrb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F58252189661', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993972635', 'Esmerilhadeira Profissional Makita M0921 9 2200W 220V', 'Uma ferramenta profissional projetada para quem exige desempenho em cortes e desbastes intensivos. Ideal para serralheiros, construtores e oficinas industriais, esta esmerilhadeira combina alto torque com ergonomia avançada, garantindo eficiência em aplicações diárias com metais e materiais de difícil usinagem. Com tecnologia Makita de dupla isolação , esta ferramenta é a escolha confiável para quem não abre mão de durabilidade e segurança. Características PrincipaisMotor de2200Wcom alta eficiência energética e baixo superaquecimento Rotação de6.600 rpmpara cortes rápidos e desbaste eficiente Compatível com discos de9 polegadas (230 mm) Punho lateral ajustávelem múltiplas posições para melhor alavancagem e controle Designcompacto e ergonômico, reduzindo esforço do operador em longas jornadas Dupla isolação elétricapara maior segurança em ambientes de trabalho Eixo padrãoM14, compatível com acessórios universais Peso estrutural de5,3 kg, equilíbrio entre potência e manuseio Corpo reforçado para trabalhos pesados e ambientes agressivos BenefíciosCom o motor de 2200W, você realiza cortes em aço, ferro e outros metais com agilidade, mesmo em espessuras elevadas. A alta rotação garante acabamento uniforme em desbaste e remoção de rebarbas, aumentando a produtividade em oficinas e canteiros de obras. O punho lateral ajustável proporciona maior estabilidade e conforto, especialmente em operações verticais ou em ângulos difíceis. O design compacto facilita o acesso a espaços estreitos, enquanto a dupla isolação protege contra choques elétricos, essencial para operações em ambientes úmidos ou mal isolados. A compatibilidade com discos de 230 mm amplia o leque de aplicações, desde corte de tubos até preparação de superfícies para solda. A durabilidade típica da linha Makita reduz custos com manutenção e substituição, sendo uma escolha inteligente para revendedores e profissionais que buscam ferramentas de longo prazo.', 1284.9, 701.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd3s-lwd7s6huupt289', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F22993972635', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
