INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23591058598', 'Kit Correia Dentada E Tensor Palio 1.5 8v 96 97 98 99 00', 'ATENÇAO PARA MOTORES 1.5 !!!!!!!!!!!!!!!!!!!!! ATENÇAO PARA MOTORES 1.5 !!!!!!!!!!!!!!!!!!!!! ATENÇAO PARA MOTORES 1.5 !!!!!!!!!!!!!!!!!!!!! Kit Correia Dentada e Tensor FIAT: Fiorino, Palio, Weekend, Siena e Uno. Compatível com: Fiorino 1.5 8V 1996/2000 Palio 1.5 8V 1996/2000 Palio Weekend 1.5 8V 1996/2000 Siena 1.5 8V 1996/2000 Itens Inclusos 01 Correia dentada 01 Rolo tensor de correia dentada A correia dentada, que também pode ser chamada de correia sincronizadora, é fundamental para o funcionamento do veículo. Ela é a responsável por segurar certas peças do interior do motor no local correto garantindo que ele tenha o ponto de ignição exato. É recomendado trocar a correia dentada atual por este Kit de correia dentada Contitech mesmo que a sua ainda não tenha dado sinais de defeito. Porque se esperar até que ela arrebente o prejuízo é muito grande. Quando ocorre o seu rompimento, ela trava o motor e pode danificar ou quebrar o eixo-comando, válvulas e pistões. O Kit de Correia Dentada Contitech com Tensor para Fiat é ideal tanto para substituição quanto para reposição. Este kit ajuda que haja a sincronização de todo o sistema de explosão do seu motor. É feito com materiais resistentes que possuem maior vida útil. Desenvolvido para Fiat Fiorino / Uno / Palio / Siena / Palio Weekend. Qualidade com o melhor preço.', 120.0, 120.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfzqmxb958xr28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353894917%2F23591058598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
