INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498904708', 'Chuteira Society Fut7 Futebol Suiço Grama Sintética Costurada Adulta Masculina Confortável Leve Pro', 'CARACTERÍSTICAS Cabedal: Laminado sintético Forro: Poliéster + Nylon dublado com espuma Palmilha: EVA com fibra Solado: Borracha com travas especiais para grama sintética / futebol society Indicação: Futebol Society, Grama Sintética, Fut7 Público‑alvo: Adulto Esta chuteira Flyboy Society foi desenvolvida para oferecer ótima performance em campos de grama sintética e jogos de society. O cabedal sintético laminado proporciona leveza e resistência, enquanto o forro acolchoado assegura conforto mesmo em partidas longas. A palmilha de EVA com fibra ajuda na absorção de impacto e no suporte ao pé, promovendo boa sensação durante corridas, arrancadas e mudanças de direção. Ideal tanto para quem joga regularmente quanto para quem curte futebol recreativo. Com um solado de borracha bem projetado com travas, ela oferece firmeza, aderência e segurança, evitando escorregões em campos sintéticos. Perfeita para partidas de Fut7 ou jogos society de final de semana. BENEFÍCIOS Maior aderência e tração em grama sintética, evitando deslizamentos indesejados. Conforto prolongado graças ao forro espumado e palmilha acolchoada; ideal para sessões de treino ou partidas longas. Excelente custo‑benefício: bom desempenho, materiais funcionais e preço acessível para o público adulto recreativo. DIFERENCIAIS TÉCNICOS Cabedal Laminado Sintético; Forro em Poliéster e Nylon Dublado com Espuma; Palmilha EVA com Fibra; Solado em Borracha com Travas para Grama Sintética O QUE ESTÁ INCLUSO? 1 par de chuteiras Flyboy Society Adulto O pedido acompanha nota fiscal? Sim, acompanham nota fiscal Precisa de ajuda? Em caso de dúvidas como numeração, cores disponíveis ou política de troca, utilize o campo de perguntas', 244.15, 134.9, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhjfiz8pdbeu5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F23498904708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
