INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198738125', 'Bolsa Honolulu Colcci Techfit Meia Lua Pequena Feminina Transversal Alça Dupla Casual', 'A Bolsa Feminina Colcci Honolulu Meia Lua Pequena é perfeita para quem busca estilo, praticidade e versatilidade em um único acessório. Com o design meia lua, tendência forte da moda, ela traz um visual moderno e elegante para compor looks casuais ou sofisticados em qualquer estação. Confeccionada em Colcci Techfit, material leve, resistente e durável, a bolsa oferece excelente acabamento e praticidade no dia a dia. Seu tamanho compacto é ideal para carregar os itens essenciais com organização, sem abrir mão do estilo. O modelo conta com duas alças: Alça curta de mão, delicada e elegante Alça longa transversal (crossbody) com ajuste, garantindo mais conforto e versatilidade O logo Colcci centralizado e o acabamento em costura aparente trazem um toque moderno e sofisticado, valorizando ainda mais o design da peça. Perfeita para o dia a dia, passeios, viagens ou composições fashionistas.', 229.99, 189.9, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc98ffei2vvka8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F728423102%2F22198738125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
