INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399647550', 'Suplemento Alimentar Macrogard Pasta 60gr para Gatos', 'MACROGARD PET Pasta APRESENTAÇÃO: Cartucho contendo 1 bisnaga de 60 g INDICAÇÃO DE USO: MACROGARD PET Pasta é um suplemento alimentar composto por β¬-1,3/1,6-glucanas purificadas derivadas do extrato de parede de levedura. Indicado para o suporte ao sistema imunológico de gatos que se beneficiem do aporte desse nutriente. MODO DE USAR: Administrar 5 cm (2 g) de pasta a cada 5 kg de peso corporal, diretamente na boca do animal, sobre as patas dianteiras ou sobre o alimento, 1 vez ao dia ou a critério do profissional responsável pela nutrição de seu animal. COMPOSIÇÃO: Extrato de parede de levedura (betaglucana), hidrolisado de fígado de suíno (palatabilizante), metilparabeno, sorbato de potássio, goma xantana, glicerina purificada (glicerol), sorbitol e água.', 146.0, 146.0, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7rd5c-m6zj6260kgpn63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F19399647550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
