INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17318665114', 'Alicate Furador Redondo Crop-a-Dile We R', 'Alicate Furador Redondo Crop-a-Dile We R Faça Furos em Materiais Extra Grossos com Facilidade O Alicate Furador Redondo We R permitirá que você faça furos em furos papel holler, alumínio fino, plástico, tecidos, couro, estanho fino e muito mais. Este Furador alcança até 5,08 cm a partir da borda do material, além de oferecer a alta performance e a força de furo da Crop-a-Dile. O Alicate Furador Redondo We R trabalha com o tamanho padrão de furos de 0,64 cm de diâmetro ou ainda 0,42 cm de diâmetro, que é otimo para fazer detalhes. Além de possuir guias de alinhamento ajustáveis, o Alicate Furador Redondo We R ainda vem com uma trava para mantê-lo fechado quando não estiver em uso. O Alicate Furador Redondo We R ainda tem um recipiente que recolhe os restos papéis picados no furo. Suas alças de silicone proporcionam conforto no uso e agregam design à ferramenta. É ideal para para fazer cartões, livros, scrapbooking e muito mais.', 194.8, 194.8, NULL, 'Stationery > Art Supplies > Others', 'https://cf.shopee.com.br/file/d3fa552cb5feae725a00c3e0c61b9b80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660248852%2F17318665114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
