INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44705511937', 'Prato para Bolo com Pé e Tampa Coração 25,5cm x 29cm Cristal', 'Prato para Bolo com Pé e Tampa Coração 25,5cm x 29cm Cristal Encante à primeira vista ao servir seus doces. Encante à primeira vista ao servir seus doces.Feito em cristal de alta qualidade, o Prato para Bolo com Pé e Tampa Coração combina elegância e romantismo em cada detalhe. Seu design com tampa em formato de coração protege e valoriza bolos, tortas e outras delícias, tornando qualquer ocasião ainda mais especial. Ideal para receber com charme e apresentar com brilho. • Cristal de alta qualidadeBrilho refinado e resistência que elevam a apresentação das suas receitas. • Design com tampa em formato de coraçãoUm toque romântico que encanta e diferencia. • Altura com péDestaque extra para bolos e sobremesas, criando composições elegantes à mesa. • Tamanho funcionalIdeal para servir bolos médios, tortas e doces diversos com sofisticação. Sirva com amor, apresente com elegância. A Lyor transforma momentos à mesa em celebrações inesquecíveis. O Prato para Bolo com Pé e Tampa Coração é a escolha perfeita para quem deseja unir beleza, proteção e romantismo ao servir. Contém: 1 Prato para Bolo com Pé 1 Tampa Medidas Produto: Altura 25,50cm x Largura 29,00cm x Comprimento 29,00cm Peso: 4,20Kg Lavar com detergente neutro, esponja macia e secar imediatamente. Não lavar em máquinas, não utilizar produtos químico.', 296.0, 207.99, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mk146vep6ubsdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F44705511937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
