INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47754762922', '6 Bowls Lyor King de Vidro 12,5cm x 5cm', '6 Bowls Lyor King de Vidro 12,5cm x 5cm Eleve a apresentação de suas refeições com o Conjunto 6 Bowls de Vidro King da Lyor. Com dimensões de 12,5cm x 5cm cada, esses bowls oferecem não apenas funcionalidade, mas também um toque sofisticado para servir uma variedade de pratos. Dimensões PráticasCada bowl possui dimensões práticas para facilitar o manuseio e a apresentação dos pratos. Versatilidade com ElegânciaSirva suas criações culinárias com versatilidade e elegância, garantindo uma apresentação impecável. Conjunto CompletoCom seis bowls, o conjunto é perfeito para receber convidados ou para uso cotidiano. Seja para ocasiões especiais ou para adicionar um toque de sofisticação ao dia a dia, o Conjunto 6 Bowls de Vidro King da Lyor é a escolha perfeita. Celebre a diversidade de sabores com estilo, oferecendo aos seus convidados uma experiência gastronômica completa e memorável. Lyor - Soluções completas para o seu Lar. Contém: 6 Bowls 12,7X5,2Cm Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 5,50cm x Largura 12,50cm x Comprimento 12,50cm Peso: 1,50Kg Cor: Incolor Material: Vidro Lavar com detergente neutro, esponja macia e secar imediatamente. Não lavar em máquinas, não utilizar produtos químico.', 53.0, 37.99, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/sg-11134201-8262b-ml5m7dd5l0qp1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F47754762922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499380639', '6 Xícaras de Café Wolff Versa de Porcelana Prata Branco 90ml', '6 Xícaras de Café Wolff Versa de Porcelana Prata Branco 90ml Conjunto 6 Xícaras de Café com Pires de Porcelana e Suporte Versa Prata/Branco 90ml - Wolff Desfrute de momentos de elegância e praticidade com o Conjunto de 6 Xícaras de Café com Pires de Porcelana e Suporte Versa Prata/Branco 90ml da Wolff. Design SofisticadoCada xícara e pires apresenta um design moderno em branco, com detalhes em prata no suporte, adicionando um toque de elegância à sua mesa de café. Porcelana de QualidadeFabricadas com porcelana de alta qualidade, as xícaras e pires são duráveis, resistentes e mantêm a temperatura do café por mais tempo, garantindo uma experiência de degustação perfeita. Capacidade IdealCom capacidade para 90ml, as xícaras são perfeitamente dimensionadas para servir porções generosas do seu café favorito, proporcionando momentos de prazer a cada gole. Suporte PráticoO suporte prata oferece uma maneira conveniente de armazenar e exibir as xícaras e pires, mantendo sua mesa organizada e elegante. Conjunto CompletoCom seis xícaras, seis pires e um suporte incluídos, este conjunto é perfeito para receber convidados ou desfrutar de momentos especiais em família. Adicione um toque de charme e requinte à sua mesa de café com o Conjunto de 6 Xícaras de Café com Pires de Porcelana e Suporte Versa Prata/Branco 90ml da Wolff. WOLFF. A melhor experiência em receber, servir e decorar! Contém: 6 Xícaras 90Ml 8,1X6,3X5,2Cm / 6 Pires 12X1,8Cm / 1 Suporte Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 14,00cm x Largura 18,50cm x Comprimento 26,50cm Peso: 1,77Kg Cor: Prata Material: Porcelana Lavar com detergente neutro, esponja macia e secar imediatamente. Não utilizar outr