INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399240501', 'Cano Água VECTRA 1994/1996 - 30487 - VC403', 'Cano Água VECTRA 1994/1996 (CD/GLS/GSI) - Motor 2.0/2.2 8/16v - (Tubo Entr. D Água Bloco Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 19.02, 19.02, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rav7-maj6slpzx942cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21399240501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099438169', 'Kit Carenagem Fan 125 2005 2006 2007 2008 Titan 125 2000 2001 2002 2004 Preto + Tampa De Ferramentas', 'Kit Carenagem Fan 125 05-08 Titan 125 00-04 Preto + Tampa De Ferramentas Sua CG 125 está com os plásticos riscados ou faltando peças? 😟 Recupere o orgulho da sua moto com o Kit Carenagem Completo da All Moto Parts, o único que já vem com a Tampa de Ferramentas inclusa! Produzido pela Wester, fornecedora das principais montadoras, este kit é fabricado em termoplástico de alta resistência. O acabamento em preto injetado garante que a cor não descasque e suporte as variações de temperatura e o sol do dia a dia sem esbranquiçar precocemente. É o encaixe perfeito, sem necessidade de gambiarras ou adaptações. ✅ DIFERENCIAIS DESTE KIT COMPLETO: COMBO 6 PEÇAS: Inclui as carenagens principais e a tampa inferior de ferramentas. ALTA RESISTÊNCIA: Plástico injetado flexível que absorve a vibração da CG 125 sem rachar. ACABAMENTO PRETO BRILHANTE: Cor integrada à massa do plástico, garantindo maior durabilidade contra riscos. PADRÃO ORIGINAL: Desenvolvido seguindo as medidas e pontos de fixação originais da Honda. QUALIDADE WESTER: Segurança e durabilidade de quem é referência no mercado de reposição. 🏍️ COMPATIBILIDADE GARANTIDA: Honda Fan 125: Anos 2005, 2006, 2007 e 2008. Honda Titan 125 (KS / ES / KSE): Anos 2000, 2001, 2002, 2003 e 2004. 📦 CONTEÚDO DA EMBALAGEM: 01 Paralama Dianteiro. 02 Tampas Laterais Superiores (Par). 02 Rabetas Laterais (Par). 01 Tampa Lateral Inferior (Caixa de Ferramentas). Nota: Não acompanha adesivos ou parafusos ℹ️ INFORMAÇÕES TÉCNICAS: Marca: Wester. Material: Termoplástico de alta resistência (Injetado). Cor: Preto. Dica: Para um brilho ainda mais intenso e proteção extra, recomendamos a aplicação de uma cera protetora após a instalação. All Moto Parts – Detalhes que transformam sua moto. Ficou com dúvida sobre o encaixe? 🤔 Nos chame no CHAT! Clique em "Comprar Agora" e deixe sua Honda impecável novamente! 🚀 #TAGS #KitCarenagem #Titan125 #Fan125 #Wester #AllMotoParts #TampaFerramentas #MotoPeças #RestauraçãoMoto #HondaCG #CarenagemPreta', 86.0, 76.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-820lt-mn5oja6z5bepa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791168756%2F23099438169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
