INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794291579', 'Molinete Micro SpeedFire 1000 - Albatroz', 'Molinete Micro SpeedFire 1000 - Albatroz Na modalidade de pesca ultra-light é importante que o molinete tenha o tamanho ideal para que seja leve (light) mas ao mesmo tempo garanta que o pescador consiga fisgar o peixe no tempo certo da batida, o Molinete SpeedFire da Albatroz atende esta questão em todos os quesitos! Um molinete compacto, extremamente leve, com 6 rolamentos e Drag de 5,2kg. Possui Knob emborrachado para maior conforto e carretel em alumínio CNC Forjado para maior resistência. Conta ainda com sistema Anti Reverso, corpo em grafite reforçado e arco reforçado. Especificações Fabricante: Albatroz Modelo: Micro SpeedFire 1000 Rolamentos 5+1 Sistema Anti-Reverso Rolete(Arco) com Rolamento Eixo Principal com Rolamentos Corpo em Grafite de Alta Resistência Carretel em Alumínio CNC Carretel Raso e Cônico para Arremesso rápido da Linha Manivela em Alumínio CNC com Sistema infinito Anti-Reverso Knob Emborrachado Drag: 5.2kg Gear Ratio: 5.2:1 Capacidade de Linha 0.18mm/100m 0.20mm/85m 0.25/60m', 258.9, 169.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-md3rkxml9dto93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F22794291579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253853402', 'Kit Lixeira Bold 6L Preto + Escova Sanitária + Porta Sabonete - Ou', 'Lixeira Bold 6L Preto - Ou Com capacidade de 6 litros e fabricada em material resistente (PP). A lixeira Bold é a escolha perfeita para quem busca um design minimalista e moderno. Com bordas arredondadas e acabamento fosco, ela se integra perfeitamente a qualquer ambiente. Além de ser esteticamente atraente, a lixeira Bold é prática e fácil de limpar, tornando-se uma escolha inteligente para sua casa ou escritório. Especificações Marca: Ou Altura: 22cm Largura: 20cm Profundidade: 20cm Escova Sanitária Bold Preto - Ou A escova sanitária Bold combina estilo e funcionalidade. Ela foi pensada e desenvolvida para uma limpeza eficiente e também para manter o seu banheiro sempre higiênico e agradável. Fabricada em material resistente PP + NYLON, com bordas arredondadas e design minimalista, ela ainda deixa o seu banheiro mais bonito. Especificações Marca: Ou ALtura: 35cm Largura: 10cm Profundidade: 10cm Porta Sabonete Liquido Bold Preto - Ou O porta sabonete líquido Bold é a escolha perfeita para aqueles que buscam um toque de elegância e simplicidade na decoração do banheiro. Com bordas arredondadas e design minimalista, ele combina perfeitamente com qualquer estilo de decoração. Além disso, sua construção resistente e fácil de limpar garante a higiene e praticidade que você precisa para manter seu banheiro organizado. Fabricado em material PP + PS com capacidade de 300ml. Especificações Marca: Ou ALtura: 9cm Largura: 8cm Profundidade: 13cm', 132.9, 126.26, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mjsspehzuwp074', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F58253853402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899576991', 'Contorno em Bastão Marrom Médio - Contour Stick Medium Océane Limited 14g', 'As Técnicas de Contorno Conquistaram Nossos Corações Por Fazerem Total Diferença Na Produção. e Nada Melhor do Que Usar Um Produto Prático Na Hora de Disfarçar As Áreas Estratégicas do Rosto, Não Acha? Conheça o Contour Stick, o Item Que Vai Se Tornar Seu Queridinho! Esse Contorno em Bastão É Aplicado Direto Nas Regiões Desejadas, Sendo Super Preciso e Prático. para Ter Aqueles Traços Faciais Bem Definidos Dignos de Make Profissional, o Produto É Facilmente Esfumado com Um PincelOu Esponja de Maquiagem. ou Seja, Não Importa a Prática Que Você Tenha com Maquiagem, Você Não Vai Ter Dificuldade em Usar o Contour Stick, Tá? E Nós Vamos Explicar o Porquê Disso: Sua Fórmula Traz Cera de Candelila e Óleo de Semente de Jojoba, Ativos Que Garantem Uma Emoliência Incrível para Espalhar o Produto e Ainda Deixar Uma Textura Cremosa com Aspecto Suave. Além Disso, Esse Contorno Foi Desenvolvido para Não Escorrer e Não Deixar a Pele Oleosa. Com Acabamento Matte, o Contour Stick Também Entrega Naturalidade à Produção. Você Vai Amar o Efeito Que Fica No Rosto! a Cor Medium É Um Tom de Marrom Médio Que Cai Bem em Diversos Tons de Pele. e Ainda Possui Uma Fórmula de Alta Durabilidade, Deixando a Maquiagem Impecável Pelo Tempo Que Você Precisar! E Não É Só Isso: Contour Stick É Vegano e Ainda Tem Uma Embalagem Compacta para Levar Na Bolsa. Você Pode Criar Qualquer Tipo de Contorno com a Facilidade Que Sempre Quis! Para Que Serve o Contorno em Bastão? O Contour Stick Foi Pensado para Criar Aqueles Efeitos Sombreados No Rosto, Que Deixam Os Traços Faciais Mais Definidos, Sabe? Porém, Ele Faz Isso de Forma Prática para Que Você Possa Passá-Lo Diretamente Na Pele e Esfumar com Facilidade. e Ainda Deixa Um Resultado Lindo, Que Eleva a Produção. Não Tem Como Não Se Apaixonar! Posso Usar o Contour Stick Na Maquiagem do Dia a Dia? Sim! Esse Contorno em Bastão Foi Pensado para Dar Profundidade Ao Rosto com Naturalidade, Sendo Ótimo para Usar em Qualquer Ocasião, Seja No Trabalho ou Numa Festa. É Só Seguir Sua Rotina de Cuidados com a Pele e Sempre Lembrar de Removê-Lo No Final do Dia, Ok?', 59.9, 59.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mr22paczg3cwc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F20899576991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
