INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799596572', 'Pistola AirSoft Spring Desert Eagle M39G 6mm Preta Double Eagle+Maleta+Esfera+Alvo+Porta Alvo', 'Pistola AirSoft Spring M39G 6mm Preta - Double Eagle A Pistola Airsoft Spring M39G 6mm Preta da Double Eagle é a escolha perfeita para iniciantes no mundo do Airsoft ou para aqueles que desejam apenas se divertir atirando em latas no quintal. Com uma velocidade de saída de 200 pés por segundo, esta pistola proporciona uma experiência emocionante. Esta pistola é alimentada por mola, o que significa que basta engatilhar o mecanismo e disparar. Rápida, limpa, econômica e fácil de manter, não requer nenhum fluído propulsor ou bateria para operar, estando pronta para ação imediatamente. Se você procura uma pistola Airsoft divertida e confiável, sua busca acabou! Com um corpo construído em plástico resistente, esta pistola possui um carregador removível com capacidade para 12 tiros. Além disso, possui mira red dot, proporcionando maior precisão e diversão. Com um alcance efetivo de cerca de 12 metros, é perfeita para brincadeiras ao ar livre. Não espere mais para se divertir! Adquira já sua Pistola Airsoft Spring M39G 6mm Preta e desfrute de momentos emocionantes com seus amigos! Especificações Marca: Double Eagle Modelo: M39G 6mm Tipo: Pistola Airsoft Spring Material: Corpo em plástico resistente Cor: Preta Peso: 400g Velocidade: 200 pés por segundo Alcance Efetivo: ~12 metros Capacidade do Carregador: 12 tiros Acompanha mira red dot Contém: 1 Pistola AirSoft Spring Desert Eagle M39G 6mm Preta 2000 Esferas 0.12g 1 Porta Alvo 10 Alvos 1 Maleta ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 698.9, 209.67, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ra10-m54mm8h6zmxq49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F18799596572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201414699', 'Kit 2x Sabonete Líquido Íntimo Feminino Vagisil Odor Block 354ml', 'Vagisil Sabonete Líquido Íntimo Odor Block. Por que Odor Block? O sabonete Odor Block® tem proteção tripla contra odores: limpa suavemente com a tecnologia patenteada Odor Block e possui um aroma leve e puro, ajudando a impedir que o odor se forme. Desenvolvido para a pele mais íntima do corpo, é suave para a pele e forte contra o odor.', 79.9, 67.92, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mht95jydq5mu45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1485857970%2F58201414699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
