INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10069631905', 'Árvore Do Comando Titan/fan E Nxr 160 296 Graus Preparado', 'COMANDO VÁLVULAS Marca: MPCRACING Modelo: CG 160 START 160 FAN 160 Levante aprox 6.4 MM CABO CENTELHA O cabo de vela é uma extensão do cabo de bobina de ignição. O cabo possui cachimbo em silicone importado resistente ao calor (300c) e condições externas, cabo de ignição em silicone de 7 mm e também um componente eletrônico que facilita a condução de energia, fazendo com que ela seja contínua, sem refluxo. O cabo apresenta baixa resistência e foi desenvolvido para maximizar o rendimento do motor. A baixa resistência reduz a perda de potência da faísca de ignição, melhorando assim a aceleração, proporcionando marcha lenta suave e queima de combustível mais limpa. Benefícios: Protege CDI e BOBINA contra refluxo de corrente elétrica Maior condutividade Mais torque e potência em todos os giros Maior isolamento Reduz o consumo de combustível Redução na emissão de gases nocivos ao meio ambiente Melhora na resposta do motor em qualquer marcha', 179.99, 179.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgmogz7lfn5zd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545730812%2F10069631905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20630520285', 'Conduite 3/4" Corrugado Eletroduto Reforçado Preto 50 Metros Dual', 'O Eletroduto Corrugado 3/4" 50 Metros Reforçado Dual para Instalações Elétricas é a solução perfeita para quem busca resistência e durabilidade em seus projetos. Fabricado em polietileno de alta densidade, este eletroduto proporciona excelente proteção mecânica e isolamento para cabos elétricos. Sua cor preta garante discrição e proteção contra raios UV, tornando-o ideal para diversas aplicações. Com um comprimento de 50 metros e diâmetro de 3/4 polegada, este eletroduto é compatível com a maioria dos cabos elétricos e de comunicação. Seu formato corrugado oferece flexibilidade superior, facilitando a instalação mesmo nas situações mais desafiadoras. Vantagens: Material resistente feito de polietileno de alta densidade Extensão de 50 metros para longas instalações Diâmetro de 3/4 polegada, ideal para diversos cabos Cor preta que oferece proteção UV Excelente proteção mecânica contra danos Flexibilidade melhorada para fácil instalação Especificações técnicas: Marca: Dual Comprimento: 50 metros Diâmetro: 3/4 polegada Cor: Preto Material: Polietileno de alta densidade Resistente a desgastes e impactos Alta resistência a produtos químicos Conteúdo da embalagem: 1 Rolo de 50m de Eletroduto Corrugado 3/4" Reforçado Dual Garantia: 3 meses de garantia pelo fabricante', 85.9, 59.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3m6d6m6g7a3ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F20630520285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
