INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793197772', 'Sensor Velocidade Gm D20 1991 a 1996 - 516097 - 7300', 'Sensor Velocidade Gm D20 1991 a 1996 516097 7300 4.1 12v - 3 Pinos - 6 Pulsos - Rosa Informa com precisão a velocidade do veículo ao computador da injeção eletrônica. Esta informação é fundamental para o controle da injeção do combustível e nos casos de desaceleração o corte deste para a redução do consumo e emissões de poluentes (CUT-OFF). Localizado geralmente na caixa de câmbio ou próximo ao eixo da roda do veiculo.', 61.56, 61.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd5t-luf6i94ys3an89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23793197772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892533294', 'FIltro Ar Condicionado RAV4 2013/2018 - 37304 - AKX1965', 'FIltro Ar Condicionado RAV4 2013/2018 Motor 2.0 16v Gasolina - (Automático/Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 29.59, 29.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7ratu-maovk0e82v0w2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22892533294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
