INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094417160', 'Correia de Acessórios p/ DOBLO/PALIO/SIENA/UNO- Contitech', 'A correia de acessórios da ContiTech é projetada para fornecer transmissão de potência eficiente entre vários componentes do motor, como o alternador, a bomba de água, a bomba de direção hidráulica e o compressor do ar condicionado. Fabricada com materiais de alta qualidade e tecnologia avançada, a correia oferece excelente resistência ao desgaste, durabilidade e desempenho confiável. A ContiTech, uma marca da Continental, é reconhecida por seus produtos inovadores e de alta precisão, garantindo segurança e eficiência para os sistemas automotivos. Especificações: - Peso bruto; 0,142 Kg - Marca; Contitech - Código do Fabricante; 5PK1175 - Comprimento; 1175 mm - Função; ALTERNADOR / AR CONDICIONADO - Largura; 18 mm - Modelo; MICRO V - Perfil automotivo; PK - Quantidade de lamelas (lâminas); 5 Aplicação: - FIAT DOBLO/PALIO/SIENA/UNO ***Para verificar a compatibilidade da peça com o seu veículo, recomendamos que entre em contato conosco para mais informações. Observação; - Valor se refere a unidade da peça', 64.6, 48.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-mbpqfwdjcnm5fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23094417160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799906464', 'Melhor Lava a Seco 500ml limpeza sem agua para lavagem automotiva com microfibra BraClean', 'Limpador para lavagem automotiva sem uso de água. Auxilia na remoção de poeira leve e sujeiras comuns, deixando a superfície pronta para uso diário. Indicado para manutenção rápida em pintura, plásticos e vidros frios e à sombra. Instruções de uso 1- Agite o frasco antes de usar. 2- Aplique por seção, com a superfície fria e abrigada do sol. 3- Deixe agir por alguns segundos e espalhe com pano de microfibra. 4- Remova o excesso com outra microfibra limpa, sem pressionar em excesso. 5- Repita nas áreas mais sujas, trocando o lado do pano para evitar riscos. Observações: teste em área discreta. Evite superfícies muito quentes. Linha com reconhecimento do ex piloto de F1 Wilson Fittipaldi Jr e colaborações técnicas no automobilismo nacional, incluindo Porsche Cup Brasil; desenvolvimento alinhado a requisitos usuais de equipamento de fábrica.', 47.8, 40.63, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mftp28wx9hxh95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998777620%2F18799906464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
