INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999589028', 'Jogo de Cama Queen Cetim 300 Fios Buddemeyer Damask Stripes 100% Algodão Penteado 4 peças', 'CARACTERÍSTICA DO PRODUTO: Damask Stripes. Clássico e elegante. Produzido em tecido adamascado, cetim 300 fios, com acabamento ponto ajour. Tecido adamascado cetim 300 fios, 100% algodão Fio Penteado - toque acetinado e macio; acabamento de excelente qualidade Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 sobrelençol 240x250cm + 1 lençol 160x200x40cm + 2 fronhas 50x70cm COMPOSIÇÃO: Tecido cetim adamascado 300 fios - 100% algodão, Fio Penteado TIPO DE MATERIAL: Tecido cetim adamascado 300 fios - 100% algodão, Fio Penteado DESCRIÇÃO: Jogo de cama queen Damask Stripes. Em tecido 100% algodão Fio Penteado, cetim 300 fios de excelente qualidade. Para altura de colchão até 40cm. A coleção Damask Stripes da Buddemeyer é produzida em tecido adamascado cetim, com acabamento em bordado ponto ajour, produto sofisticado que proporciona um toque acetinado, macio e com brilho. Fronha 3 abas com acabamento em ponto ajour; lençol com elástico para altura de colchão até 40cm, sobrelençol com acabamento em ponto ajour na vira. Em tecido 100% algodão Fio Penteado, cetim 300 fios de excelente qualidade. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 60°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Temperatura máxima da base do ferro 110°C. Não usar ferro a vapor. Não lavar a seco.', 869.46, 641.2, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-7rfh3-m9ktpz3l7mzaf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F19999589028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
