INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22828611825', 'Bota Infantil Coturno Nilqi - 1500', 'A Bota Infantil Coturno Nilqi é confeccionada em Napa, com forro interno em têxtil e palmilha em EVA ultra confortável. O solado em borracha tratorada garantem segurança a todo o momento, com cano que mede quinze centímetros por vinte e cinco de circunferência aproximadamente. . MODELO: A8065005 REFERENCIA: 1500 MARCA: Nilqi MATERIAL DA PALMILHA: EVA MATERIAL INTERNO: Têxtil DETALHES: Possui um mini bolso com fechamento por fivela, nas laterais de ambos os pares. GÊNERO: Female GRUPO DE IDADE: Infant MEDIDA DO CANO: 15 cm aproximadamente CIRCUNFERÊNCIA DO CANO: 25 cm aproximadamente MATERIAL DO SAPATO: Napa', 119.99, 119.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Boots', 'https://cf.shopee.com.br/file/sg-11134201-23030-o0pv9asj66nv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F22828611825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397090703', 'Verniz Proteção Máxima Deck Base de Água Brilhante Natural Suvinil 3,6l', 'VERNIZ PROTEÇÃO MÁXIMA DECK SUVINIL 3,6L COR: NATURAL ACABAMENTO: BRILHANTE A categoria Verniz + Impregnante protege de dentro para fora. Seus produtos impregnam e criam uma película protetora impermeável que preservam e restauram muito além da superfície, deixando sua madeira ainda mais bonita. O produto Proteção Máxima Deck vem com a cor natural pronta, no acabamento acetinado. Indicado para proteção de todos os tipos de madeira, conferindo dupla proteção pois penetra nos veios da madeira formando uma película protetora. DESCRIÇÕES: Resistente ao tráfego de pessoas Proteção contra sol, chuva, mofo, algas, maresias Produto a Base de Água Acabamento Acetinado (leve brilho) Baixo Odor AMBIENTES: Exterior (lado de fora) Interior (lado de dentro) RENDIMENTO: Embalagem 3,6l = até 100 m² por demão (podendo variar de acordo com a superfície) Em caso de dúvida mande uma pergunta que nosso time já vai te responder!', 495.9, 416.5, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rbk2-lq51i9w4xm0af2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346348161%2F22397090703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
