INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298341562', 'Sapatênis Max Light Confortável Masculino Rafarillo', 'O Sneaker Rafarillo Ultratech combina tecnologia avançada para conforto e desempenho.Seu solado bidensidade, com poliuretano (PU) e poliuretano termoplástico (TPU), oferece excelente amortecimento, absorção de impactos e resistência ao desgaste. O couro de alta qualidade, junto ao solado, proporciona maciez e conforto para uso diário.Além disso, seu design moderno e elegante é fácil de combinar com diversos looks. O Rafarillo Ultratech é durável, ideal para quem busca estilo e conforto ao mesmo tempo.&nbsp;Especificações: Material: Couro Acabamento: Natural Forro: Nylon Solado: Borracha Adicionais do Produto: Ultratech é durável, ideal para quem busca estilo e conforto ao mesmo tempo. Diferencial: Feito com materiais de alta qualidade. Garantia do Fabricante: Contra defeitos de fabricação Informações adicionais: A limpeza do calçado pode ser feita com pano úmido. Não deixar submerso em água e não utilizar nenhuma forma de calor para secar. Lavar a palmilha separadamente. Guardar em local sem umidade e deixar descansar na sombra por 12 horas após o uso.&nbsp;', 379.39, 379.39, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rd4k-m7lg3bul31rb28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F865304201%2F23298341562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
