INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19007530866', 'Hot Wheels 365 Atividades e Desenhos para Colorir', 'Chegou a hora de se divertir com os desafios mais incríveis do universo alucinante dos carros Hot Wheels. Neste livro, você encontrará diversos desenhos e muitas atividades radicais. Aperte os cintos e divirta-se! Especificações Título: Hot Wheels 365 Atividades e Desenhos para Colorir Ano de edição: 0 Páginas: 288 Dimensões: 21 x 14 x 3 cm Peso: 0,409 kg ISBN: 9788538088752 Editora: Ciranda Cultural Assunto: Infantil Família: Livros', 12.25, 12.25, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/a35d2f4edc76dedb55e7a00f38a43e53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19007530866', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13293351782', 'Livro Em Defesa de Cristo | Lee Strobel', 'Em Defesa de Cristo EM DEFESA DE CRISTO mostra a investigação do cético Lee Strobel, jornalista ateu premiado que faz a cobertura dos tribunais de Chicago. Sua esposa Leslie decide seguir a Cristo, gerando nele uma grande inquietação: Que sentido teria uma história antiquada com jeito de lenda? Deus existe? Jesus é uma pessoa de verdade com sua existência comprovada pela história? Aplicando a sua experiência profissional e a sua formação em direito, pesquisando sobre o assunto e consultando especialistas internacionais em história, arqueologia e linguística, ele inicia uma busca detalhada da verdade. Strobel surpreende com as suas perguntas, extraindo o melhor do conhecimento de seus entrevistados. Com exemplos da vida real, ele nos conduz às melhores informações para que cheguemos as nossas melhores conclusões sobre os argumentos em defesa de Cristo. Indicado para céticos, religiosos e para o público em geral, este livro informa, estimula e edifica. Embarque nessa jornada! Título , Em ,Defesa ,de ,Cristo Autor , Lee ,Strobel Páginas , 368 Formato , 22,8 ,x ,15,4 ,x ,2 ,cm Peso , 0 ,522 ,kg ISBN , 9788578609948 Editora , Thomas ,Nelson', 46.31, 46.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/a55ba77af534f35d03f424ddf850bd46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F13293351782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23930829842', 'Diga não ao Comodismo e volte pra Corrida | Merlin Carothers', 'Diga não ao Comodismo e volte pra Corrida Não se acomode; Merlin Carothers conhecido por seus livros "Louvor que liberta" e "O Poder do louvor," descobriu que estava sendo dominado pelo desejo de viver se divertindo. A comodidade da aposentadoria e de ter tempo com folga para descansar se tornaram um embaraço para ele. Bens que deviam ajudá-lo a gozar melhor a vida, na verdade o estavam puxando para trás. "Até que Deus me acordou..." conta ele. Alcance a vitória você também; este livro vai levá-lo a descobrir formas de entretenimento e diversão que podem se tornar verdadeiros obstáculos à sua corrida cristã e roubar seu vigor espiritual. Vai ajudá-lo também a tomar atitudes firmes para que todas as áreas de sua vida sejam dedicadas à glória de Deus. Título: Diga não ao Comodismo e volte pra Corrida Subtitulo: Vença as estratégias criadas por Satnás, que podem leva-lo a "pendurar as chuteiras" espirituais. Autor: Merlin Carothers Páginas: 128 Formato: 10,5 x 18 cm Peso: 0.150 kg ISBN: 9788535803242 Editora: Betânia', 27.41, 27.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-96x1vkhmihovd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23930829842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28233682403', 'Bíblia Sagrada Leia e Anote | NVT | Letra Normal | Capa Luxo Fendi', 'Bíblia Sagrada Leia e Anote | NVT | Letra Normal | Capa Luxo Fendi Bíblia Sagrada Leia e Anote Sabemos que é no secreto que revelamos nossos maiores desejos e expressamos nossos mais íntimos pensamentos, então para te auxiliar a extrair tudo o que Deus sondar e te revelar a cerca de ti, você poderá anotar tudo nos espaços para anotação dessa bíblia. O processo é simples, leia e anote e é claro reflita sobre o que leu. Depois saia do secreto e aplique tudo o que você absorveu nessa leitura incrível, afinal de contas, estamos falando da bíblia, não basta ler, precisa viver o que leu! Já conhece a versão bíblica Nova Versão Transformadora (NVT)? Uma revisão que desde lançada tem trazido aos leitores uma incrível experiência no entendimento da palavra através do seu fácil entendimento e fidelidade nos textos originais, uma versão que muito nos agradou. Agora você terá em suas mãos uma bíblia com linguagem fiel e, ao mesmo tempo, moderna, a Bíblia Sagrada NVT com o design bem mais fininho que as bíblias convencionais, com capa dura e bordas arredondadas. Páginas:768 Formato:Altura: 20 cm Largura: 17,5 cm Profundidade: 2,5 cm', 109.82, 109.82, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7req6-m8nbj107azs975', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28233682403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
