INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14153568363', 'Autotransformador 1500VA TF-1500 Upsai', 'Autotransformador 1500VA TF-1500 Upsai A Linha TF de Autotransformadores foi desenvolvida para atender uma ampla gama de aplicações. Possui carcaça aterrada para garantir a segurança do usuário e proteção térmica está disponível em diversas potências e destina-se a equipamentos que requeiram a conversão de tensão de 120V para 220V ou de 220V para 120V. Características Converte 220V em 120V e 120V em 220V. Sensor térmico. Proteção contra sobrecarga. Instalação segura com uso de adaptador H e cabo prolongador. Carcaça metálica aterrada para garantir a segurança do usuário. Plugues e tomadas com certificação INMETRO - Padrão NBR14136. Aplicações: Residência, eletroeletrônicos, informática, áudio e vídeo, vídeo games, eletrodomésticos, camping, indústria, ar Condicionado, ferramentas e motores. Informações Técnicas - Capacidade nominal(*): 1500VA; - Voltagem de entrada / saída: 120V - 220V; - Frequência de operação: 60Hz / 50Hz (opcional); - Consumo em vazio: <2%; - Proteções: Sobrecarga / Sobre temperatura com rearme automático; - Enrolamento: Classe - H ; - Núcleo: Aço-Silico; - Temperatura de operação: 0 a 40ºC; - Umidade relativa: 0 a 95% sem condensação; - Conexões de entrada: Adaptador H. (*) Considerando regime não contínuo de operação. Observação: - Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor; - Imagens meramente ilustrativas, consulte nosso atendimento para mais detalhes.', 174.95, 174.95, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbms-lmbfvnaiz97d22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F409830325%2F14153568363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
