INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201879718', 'Caixa de Som Jbl Partybox On The Go 2 15hrs 100w', 'JBL PARTYBOX ON THE GO 2 A JBL PartyBox On The Go 2 é uma caixa de som portátil projetada para proporcionar som potente e experiência completa para festas, encontros e momentos de lazer, com tecnologia avançada e som JBL Pro de alta fidelidade. SOM JBL PRO Com 100 W RMS de potência, oferece graves encorpados, médios definidos e agudos cristalinos, garantindo qualidade sonora mesmo em ambientes amplos. SHOW DE LUZES DINÂMICO As luzes LED integradas sincronizam com o ritmo da música, criando um ambiente mais vibrante e envolvente automaticamente. KARAOKÊ COMPLETO Inclui um microfone digital sem fio com efeitos ajustáveis e função de alteração de tonalidade da música, ideal para apresentações e diversão com amigos e família. CONECTIVIDADE FLEXÍVEL Equipado com Bluetooth 5.4, entrada USB (compatível com MP3, WAV e FLAC), entrada auxiliar e entrada para guitarra. Permite controle de luzes, equalização e efeitos através do aplicativo oficial PartyBox. MOTIVOS PARA ESCOLHER ESTE MODELO - Som JBL Pro de alto desempenho - Iluminação dinâmica e sincronizada - Acompanha um microfone sem fio - Ampla conectividade - Ideal para festas, eventos e uso recreativo ESPECIFICAÇÕES TÉCNICAS - Potência: 100 W RMS - Alto-falantes: 1 woofer de 5,25" + 2 tweeters de 0,75" - Resposta de frequência: 40 Hz a 20 kHz - Relação sinal/ruído: acima de 80 dB - Bluetooth: 5.4 - Formatos USB: MP3, WAV, FLAC - Funções extras: karaokê avançado e iluminação LED DIMENSÕES DO PRODUTO SEM EMBALAGEM - Largura: 50,1 cm - Altura: 25,8 cm - Profundidade: 22,1 cm - Peso: 6,36 kg DIMENSÕES DO PRODUTO COM EMBALAGEM - Largura: 58,6 cm - Altura: 35,5 cm - Profundidade: 27,8 cm - Peso: 9,18 kg CONTEÚDO DA EMBALAGEM - 1 caixa de som PartyBox On The Go 2 - 1 microfone digital sem fio - 1 suportes para microfone - 1 alça de ombro - 1 cabo de energia - 1 guia rápido - 1 manual do usuário GARANTIA - Garantia oficial de 1 ano do fabricante', 3259.9, 1859.0, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-81zua-mkmagjgqv7yb23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F898761179%2F58201879718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
