INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19007530902', 'Frequencia | Robert Morris', 'FrequênciaO livro Frequência do pastor e autor Morris aborda um assunto sobre a comunicação de Deus para com seus servos e nos deixa uma questão aberta Você está ouvindo Deus? O autor nos explica que Deus não quer que vivamos pela consciência nem mesmo hoje pois a consciência nos lembra do conhecimento do bem e do mal Certamente uma consciência pode exercer um papel em nossas vidas se a nossa consciência for guiada e redimida por Deus O autor nos leva a entender que Deus fala sim conosco e que ele se comunica de inúmeras maneiras DEUS FALA? ELE ESTÁ FALANDO COMIGO? A BOA NOTÍCIA É SIM DEUS FALA E ELE SE COMUNICA COM VOCÊ DE INÚMERAS MANEIRAS Título Frequência Subtitulo Deus fala o tempo todo Você está ouvindo A Voz dEle? Autor Dutch Sheets Páginas 238 Formato 23 x 16 Peso 0 300kg ISBN 9788559290240 Editora LAN', 37.99, 37.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/3990364bec29c7d03c60279a6e5384ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19007530902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
